    ctx.fillStyle = mane; ctx.beginPath(); ctx.ellipse(-14, -60, 18, 10, -0.2, 0, TAU); ctx.fill();
    ctx.strokeStyle = mane; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(-38, -46); ctx.quadraticCurveTo(-56, -60, -54, -78); ctx.stroke();
