    ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.fillStyle = alpha(glow, 0.2); ctx.beginPath(); ctx.ellipse(0, -58, 24, 8, 0, 0, TAU); ctx.fill(); ctx.restore();
  }
  ctx.restore();
}

