106: export function recalc(player, full = false) {
107:   const cls = CLASSES[player.classId];
108:   const level = player.level;
109:   const g = cls.growth;
110:   const base = {
111:     attack: cls.base.attack + g.attack * (level - 1),
112:     armor: cls.base.armor + g.armor * (level - 1),
113:     hp: cls.base.hp + g.hp * (level - 1),
114:     crit: cls.base.crit + g.crit * (level - 1),
115:     critDmg: cls.base.critDmg + g.critDmg * (level - 1),
116:     hpRegen: cls.base.hpRegen + g.hpRegen * (level - 1),
117:     resourceRegen: cls.base.resourceRegen,
118:     speed: cls.base.speed,
119:   };
120:   const stone = player.stones.find((s) => s.uid === player.activeStone) ?? null;
121:   const gear = aggregateStats(player.equipment, stone, player.classId, level);
122:   const fb = FACTION_BONUS[player.faction] ?? {};
123:   const passiveArmor = player.classId === 'warrior' ? 0.12 : 0;
124:   const passiveCritDmg = player.classId === 'assassin' ? 0.15 : 0;
125:   const passiveRegen = player.classId === 'mage' ? 0.2 : 0;
126: 
127:   const stats = {
128:     attack: (base.attack + (gear.attack ?? 0)) * (1 + (fb.attack ?? 0)),
129:     armor: (base.armor + (gear.armor ?? 0)) * (1 + passiveArmor + (fb.armor ?? 0)),
130:     maxHp: Math.round(base.hp + (gear.hp ?? 0)),
131:     crit: clampCrit(base.crit + (gear.crit ?? 0)),
132:     critDmg: base.critDmg + (gear.critDmg ?? 0) + passiveCritDmg,
133:     speed: base.speed * (1 + (gear.speed ?? 0)),
134:     lifesteal: clamp((gear.lifesteal ?? 0) + (fb.lifesteal ?? 0), 0, 0.5),
135:     goldFind: gear.goldFind ?? 0,
136:     gatherSpeed: clamp(gear.gatherSpeed ?? 0, 0, 1.5),
137:     hpRegen: base.hpRegen + (gear.hpRegen ?? 0),
138:     resourceRegen: (base.resourceRegen + (gear.resourceRegen ?? 0)) * (1 + passiveRegen),
139:     maxResource: cls.base.resourceMax,
140:     power: 0,
141:     gearScore: 0,
142:   };
143:   stats.power = Math.round(stats.attack * 4 + stats.armor * 3 + stats.maxHp * 0.35 + stats.crit * 800 + stats.critDmg * 120 + stats.lifesteal * 600);
144:   stats.gearScore = Object.values(player.equipment).reduce((s, it) => s + (it ? equipScore(it) : 0), 0) + (stone ? 120 : 0);
145:   player.stats = stats;
146:   if (full || player.hp == null) player.hp = stats.maxHp;
147:   player.hp = clamp(player.hp, 0, stats.maxHp);
148:   player.resource = clamp(player.resource ?? 0, 0, stats.maxResource);
149:   return stats;
150: }
