162: export function addXP(player, amount) {
163:   if (player.level >= MAX_LEVEL) return { levels: 0, xp: 0 };
164:   const xp = Math.max(1, Math.round(amount));
165:   player.xp += xp;
166:   let levels = 0;
167:   while (player.level < MAX_LEVEL && player.xp >= xpForLevel(player.level)) {
168:     player.xp -= xpForLevel(player.level);
169:     player.level++;
170:     levels++;
171:   }
172:   if (levels > 0) {
173:     const beforeHp = player.stats.maxHp;
174:     recalc(player);
175:     player.hp = player.stats.maxHp;
176:     player.resource = player.stats.maxResource;
177:     player.lastLevelGain = { levels, beforeHp };
178:   }
179:   return { levels, xp };
180: }
