293: // ── Fusion ────────────────────────────────────────────────────────────────
294: export function fusionGroups(player) {
295:   const groups = new Map();
296:   for (const it of player.inventory) {
297:     if (it.kind !== 'equip' || !it.fusable) continue;
298:     if (!fusionResult(it)) continue;
299:     const key = it.key ?? `${it.slot}|${it.class}|${it.rarity}|${it.tier}|${it.level}`;
300:     if (!groups.has(key)) groups.set(key, { key, items: [], sample: it, result: makeFusionResult(it) });
301:     groups.get(key).items.push(it);
302:   }
303:   return [...groups.values()].sort((a, b) => b.items.length - a.items.length);
304: }
