306: export function canFuseGroup(group) { return group && group.items.length >= 4 && group.result; }
307: 
308: export function fuseGroup(player, group) {
309:   if (!canFuseGroup(group)) return null;
310:   const consumed = group.items.slice(0, 4);
311:   for (const it of consumed) {
312:     const idx = player.inventory.findIndex((x) => x.uid === it.uid);
313:     if (idx >= 0) player.inventory.splice(idx, 1);
314:   }
315:   const result = makeFusionResult(consumed[0]);
316:   if (!result) return null;
317:   addItem(player, result);
318:   return result;
319: }
