372: export function claimQuest(player, questId, opts = {}) {
373:   const q = getQuest(questId);
374:   const entry = player.quests[questId];
375:   if (!q || !entry || entry.state !== 'done') return null;
376:   entry.state = 'claimed';
377:   player.questsDone++;
378:   const r = q.rewards ?? {};
379:   const gained = { xp: 0, gold: 0, gems: 0, items: [], unlocks: [] };
380:   if (r.xp) { addXP(player, r.xp); gained.xp = r.xp; }
381:   if (r.gold) { addGold(player, r.gold); gained.gold = r.gold; }
382:   if (r.gems) { addGems(player, r.gems); gained.gems = r.gems; }
383:   if (r.gear && opts.generateGear !== false) {
384:     const it = makeEquip({ classId: player.classId, slot: r.gear.slot, rarity: r.gear.rarity, tier: r.gear.tier, level: Math.max(1, getZone(q.zone).min) });
385:     if (!addItem(player, it)) { player.storage.push(it); gained.stored = true; }
386:     gained.items.push(it);
387:   }
388:   if (r.consumable) {
389:     const c = makeConsumable(r.consumable.id, r.consumable.qty ?? 1);
390:     c.stackLimit = 20;
391:     addItem(player, c);
392:     gained.items.push(c);
393:   }
394:   if (r.mount) {
395:     if (!player.mounts.includes(r.mount)) { player.mounts.push(r.mount); gained.mount = r.mount; }
396:   }
397:   if (r.wing) {
398:     if (!player.wings.includes(r.wing)) { player.wings.push(r.wing); gained.wing = r.wing; }
399:   }
400:   if (r.title) player.title = r.title;
401:   if (r.gems && q.story) {
402:     player.completedChapters = Math.max(player.completedChapters, q.chapter);
403:     const next = ZONES.find((z) => z.unlockChapter === q.chapter);
404:     if (next) {
405:       if (!player.discoveredZones.includes(next.id)) { player.discoveredZones.push(next.id); gained.zone = next.id; }
406:     }
407:   }
408:   recalc(player);
409:   return gained;
410: }
