282:       const inCombat = this.monsters.some((m) => !m.dead && m.aggro && dist(m.x, m.y, player.x, player.y) < 300);
283:       const speedMul = inCombat ? 0.92 : 1 + (player.mount ? mountSpeed(player) : 0);
284:       const speed = player.stats.speed * speedMul;
285:       let nx = player.x + mx * speed * dt;
286:       let ny = player.y + my * speed * dt;
287:       const resolved = resolveCollision(nx, ny, this.data.props);
288:       player.x = clamp(resolved.x, 40, WORLD_SIZE - 40);
289:       player.y = clamp(resolved.y, 40, WORLD_SIZE - 40);
290:       if (Math.abs(mx) > 0.2) this.facing = mx > 0 ? 1 : -1;
291:       this.walkPhase = (this.walkPhase ?? 0) + dt * 9;
292:     }
293: 
294:     // regen
295:     if (!this.inCombat() && player.hp > 0) {
296:       player.hp = Math.min(player.stats.maxHp, player.hp + player.stats.hpRegen * dt);
297:       player.resource = Math.min(player.stats.maxResource, player.resource + player.stats.resourceRegen * dt);
298:     }
299: 
300:     if (this.attackHeld) this.tryBasicAttack();
301:     this.updateMonsters(dt);
302:     this.updateProjectiles(dt);
303:     this.updateEffects(dt);
304:     this.updateFloaters(dt);
305:     this.updateLoot(dt);
306:     this.updateInteraction();
307:     this.updateCamera(dt);
308:     this.updateNPCs();
309:     this.minimapTimer -= dt;
310:     if (this.minimapTimer <= 0) { this.drawMinimap(); this.minimapTimer = 0.35; }
311:     if (this.autosaveTimer == null) this.autosaveTimer = 20;
312:     this.autosaveTimer -= dt;
313:     if (this.autosaveTimer <= 0) { this.autosaveTimer = 25; this.save(); }
314:     // tutorial first steps
315:     if (!this.game.settings?.tutorialDone) this.tutorialProgress();
316:   }
317: 
318:   tutorialProgress() {
319:     const p = this.player;
320:     if (this.tutStep === 0 && this.moving) { this.tutStep = 1; App.ui?.tutorialStep?.(1); }
321:     if (this.tutStep === 1 && this.playerHasAttacked) { this.tutStep = 2; App.ui?.tutorialStep?.(2); }
322:     if (this.tutStep === 2 && this.playerUsedSkill) { this.tutStep = 3; App.ui?.tutorialStep?.(3); }
323:   }
324: 
325:   updateBuffs() {
326:     const now = Date.now();
327:     if (this.armorBuffUntil && now > this.armorBuffUntil) this.armorBuffUntil = 0;
328:     if (this.xpBuffUntil && now > this.xpBuffUntil) this.xpBuffUntil = 0;
329:     if (this.gatherBuffUntil && now > this.gatherBuffUntil) this.gatherBuffUntil = 0;
330:   }
331: 
332:   inCombat() {
333:     return this.monsters.some((m) => !m.dead && m.aggro && dist(m.x, m.y, this.player.x, this.player.y) < 420);
334:   }
335: 
336:   updateCamera(dt) {
337:     const viewH = VIEW_W * (this.h / this.w);
338:     const tx = clamp(this.player.x, viewH * 0 + VIEW_W / 2, WORLD_SIZE - VIEW_W / 2);
339:     const ty = clamp(this.player.y, viewH / 2, WORLD_SIZE - viewH / 2);
340:     const k = 1 - Math.pow(0.001, dt);
341:     this.camera.x += (tx - this.camera.x) * k;
342:     this.camera.y += (ty - this.camera.y) * k;
343:   }
344: 
345:   updateNPCs() {
346:     if (!this.npcs) return;
347:     for (const npc of this.npcs) {
348:       const zoneQuests = QUESTS.filter((q) => q.zone === this.zoneId && (q.npc === npc.id || (!q.npc && q.story)));
349:       let marker = null;
350:       for (const q of zoneQuests) {
351:         const e = this.player.quests[q.id];
352:         if (e?.state === 'done') { marker = 'done'; break; }
353:         if (!e) { marker = 'quest'; }
354:       }
355:       npc.marker = marker;
356:     }
357:   }
358: 
359:   // ── combat ──────────────────────────────────────────────────────────────
360:   get basicRange() { return this.player.classId === 'mage' ? 390 : this.player.classId === 'assassin' ? 105 : 118; }
361: 
362:   tryBasicAttack() {
363:     if (this.dead || this.channel) return;
364:     if (this.attackCooldown > 0) return;
365:     let target = this.target;
366:     if (!target) {
367:       target = this.nearestMonster(this.basicRange + 60);
368:       if (target) this.targetUid = target.uid;
369:     }
370:     if (!target) {
371:       if (this.attackHeld && this.time - (this.lastNoTargetToast ?? 0) > 2) {
372:         this.lastNoTargetToast = this.time;
373:         this.notify(t('hud.noTarget'));
374:       }
375:       this.attackCooldown = 0.35;
376:       return;
377:     }
378:     const d = dist(this.player.x, this.player.y, target.x, target.y);
379:     if (d > this.basicRange + (target.boss ? 30 * target.scale : 10)) {
380:       this.targetUid = null;
381:       this.attackCooldown = 0.3;
382:       return;
383:     }
384:     this.attackCooldown = this.player.classId === 'assassin' ? 0.55 : this.player.classId === 'warrior' ? 0.72 : 0.82;
385:     this.attackAnim = 1;
386:     this.playerHasAttacked = true;
387:     this.facing = target.x >= this.player.x ? 1 : -1;
388:     const empower = this.empowered > 0 ? 1.8 : 1;
389:     this.empowered = 0;
390:     let dmg = this.player.stats.attack * (0.92 + Math.random() * 0.16) * empower;
391:     const crit = Math.random() < this.player.stats.crit;
392:     if (crit) dmg *= this.player.stats.critDmg;
393:     this.hitMonster(target, dmg, { crit, type: 'basic' });
394:     this.gainResource(this.player.classId === 'warrior' ? 13 : this.player.classId === 'assassin' ? 9 : 5);
395:     this.applyLifesteal(dmg);
396:     this.addEffect({ kind: this.player.classId === 'mage' ? 'bolt' : 'slash', x: this.player.x, y: this.player.y - 34, tx: target.x, ty: target.y - 30, color: this.player.classId === 'mage' ? '#a8d8ff' : '#f0d090', life: 0.24, maxLife: 0.24, angle: Math.atan2(target.y - this.player.y, target.x - this.player.x) });
397:     this.sfx(this.player.classId === 'mage' ? 'cast' : 'slash');
398:     this.shakeTime = Math.max(this.shakeTime, 0.08);
399:   }
400: 
401:   useSkill(indexOrId) {
402:     if (this.dead || this.channel) return false;
403:     const cls = CLASSES[this.player.classId];
404:     const skill = typeof indexOrId === 'number' ? cls.skills[indexOrId] : cls.skills.find((s) => s.id === indexOrId);
405:     if (!skill) return false;
406:     if (this.player.level < skill.unlock) {
407:       this.notify(t('skill.unlockAt', { lv: skill.unlock }));
408:       return false;
409:     }
410:     if ((this.cooldowns[skill.id] ?? 0) > 0) return false;
411:     const res = this.player.classId === 'warrior' ? 'rage' : this.player.classId === 'mage' ? 'mana' : 'energy';
412:     if (this.player.resource < skill.cost) {
413:       this.notify(t('toast.noResource', { resource: t(`common.${res}`) }), 'bad');
414:       return false;
415:     }
416:     const target = this.target ?? this.nearestMonster(skill.type === 'single' ? skill.range : 300);
417:     if ((skill.type === 'single' || skill.type === 'dash') && (!target || dist(this.player.x, this.player.y, target.x, target.y) > skill.range + 40)) {
418:       this.notify(t('toast.needTarget'));
419:       return false;
420:     }
421:     this.player.resource -= skill.cost;
422:     this.playerUsedSkill = true;
423:     this.cooldowns[skill.id] = skill.cd;
424:     this.facing = target && target.x < this.player.x ? -1 : 1;
425:     this.sfx('cast');
426:     if (skill.type === 'single') {
427:       this.doSingleSkill(skill, target);
428:     } else if (skill.type === 'aoe') {
429:       this.doAoeSkill(skill);
430:     } else if (skill.type === 'ground') {
431:       this.doGroundSkill(skill, target);
432:     } else if (skill.type === 'buff') {
433:       this.doBuffSkill(skill);
434:     } else if (skill.type === 'dash') {
435:       this.doDashSkill(skill, target);
436:     }
437:     this.save();
438:     return true;
439:   }
440: 
441:   skillDamage(skill, mult = 1) {
442:     let dmg = this.player.stats.attack * skill.mult * mult * (0.94 + Math.random() * 0.12);
443:     const crit = Math.random() < this.player.stats.crit;
444:     if (crit) dmg *= this.player.stats.critDmg;
445:     return { dmg, crit };
446:   }
447: 
448:   doSingleSkill(skill, target) {
449:     const { dmg, crit } = this.skillDamage(skill);
450:     if (this.player.classId === 'mage') {
451:       this.projectiles.push({ x: this.player.x, y: this.player.y - 40, tx: target.x, ty: target.y - 30, speed: 760, color: skill.color, life: 1.2, onHit: () => this.hitMonster(target, dmg, { crit, skill }), trail: skill.color });
452:       this.addEffect({ kind: 'cast', x: this.player.x, y: this.player.y - 30, color: skill.color, life: 0.4, maxLife: 0.4 });
453:     } else {
454:       this.addEffect({ kind: 'slash', x: this.player.x, y: this.player.y - 34, tx: target.x, ty: target.y - 30, color: skill.color, life: 0.32, maxLife: 0.32, angle: Math.atan2(target.y - this.player.y, target.x - this.player.x) });
455:       this.hitMonster(target, dmg, { crit, skill });
456:       if (skill.effect === 'stun') { target.stunUntil = this.time + 1.45; this.floater(target.x, target.y - 70, t('combat.stunned'), '#f2d27a'); }
457:       if (skill.effect === 'poison') { target.poisonUntil = Math.max(target.poisonUntil, this.time + 6); target.poisonTick = 0; }
458:     }
459:     this.applyLifesteal(dmg);
460:   }
461: 
462:   doAoeSkill(skill) {
463:     const targets = this.monsters.filter((m) => !m.dead && dist(m.x, m.y, this.player.x, this.player.y) <= skill.radius + (m.boss ? 26 * m.scale : 0));
464:     this.addEffect({ kind: 'ring', x: this.player.x, y: this.player.y - 12, r: skill.radius, color: skill.color, life: 0.55, maxLife: 0.55 });
465:     this.addEffect({ kind: 'burst', x: this.player.x, y: this.player.y - 30, color: skill.color, life: 0.4, maxLife: 0.4 });
466:     for (const m of targets) {
467:       const { dmg, crit } = this.skillDamage(skill, 0.9 + Math.random() * 0.2);
468:       this.hitMonster(m, dmg, { crit, skill });
469:       if (skill.effect === 'slow') { m.slowUntil = this.time + 4; this.floater(m.x, m.y - 66, t('combat.slowed'), '#9fe8ff'); }
470:       if (skill.effect === 'bleed') { m.burnUntil = Math.max(m.burnUntil, this.time + 4); m.burnTick = 0; }
471:       this.applyLifesteal(dmg);
472:     }
473:     if (!targets.length) this.notify(t('toast.needTarget'));
474:     this.shakeTime = Math.max(this.shakeTime, 0.16);
475:   }
476: 
477:   doGroundSkill(skill, target) {
478:     const tx = target ? target.x : this.player.x + this.facing * 150;
479:     const ty = target ? target.y : this.player.y;
480:     this.addEffect({ kind: 'telegraph', x: tx, y: ty, r: skill.radius, color: skill.color, life: 0.7, maxLife: 0.7, ground: true });
481:     setTimeout(() => {
482:       if (!this.running) return;
483:       this.addEffect({ kind: 'meteor', x: tx, y: ty, r: skill.radius, color: skill.color, life: 0.8, maxLife: 0.8 });
484:       this.addEffect({ kind: 'ring', x: tx, y: ty - 8, r: skill.radius, color: skill.color, life: 0.55, maxLife: 0.55 });
485:       for (const m of this.monsters) {
486:         if (m.dead) continue;
487:         if (dist(m.x, m.y, tx, ty) <= skill.radius + 12) {
488:           const { dmg, crit } = this.skillDamage(skill, 0.92 + Math.random() * 0.16);
489:           this.hitMonster(m, dmg, { crit, skill });
490:           if (skill.effect === 'burn') { m.burnUntil = Math.max(m.burnUntil, this.time + 5); m.burnTick = 0; }
491:           this.applyLifesteal(dmg);
492:         }
493:       }
494:       this.shakeTime = Math.max(this.shakeTime, 0.3);
495:     }, 650);
496:   }
497: 
498:   doBuffSkill(skill) {
499:     const heal = this.player.stats.maxHp * 0.24;
500:     this.player.hp = Math.min(this.player.stats.maxHp, this.player.hp + heal);
501:     this.armorBuffUntil = Date.now() + 8000;
502:     this.floater(this.player.x, this.player.y - 74, `+${Math.round(heal)}`, '#8ce07a');
503:     this.addEffect({ kind: 'pillar', x: this.player.x, y: this.player.y, color: skill.color, life: 0.9, maxLife: 0.9 });
504:   }
505: 
506:   doDashSkill(skill, target) {
507:     const angle = Math.atan2(target.y - this.player.y, target.x - this.player.x);
508:     let nx = target.x - Math.cos(angle) * 48;
509:     let ny = target.y - Math.sin(angle) * 48;
510:     const resolved = resolveCollision(nx, ny, this.data.props);
511:     this.addEffect({ kind: 'dash', x: this.player.x, y: this.player.y - 30, tx: resolved.x, ty: resolved.y - 30, color: skill.color, life: 0.4, maxLife: 0.4 });
512:     this.player.x = clamp(resolved.x, 40, WORLD_SIZE - 40);
513:     this.player.y = clamp(resolved.y, 40, WORLD_SIZE - 40);
514:     this.camera.x = this.player.x; this.camera.y = this.player.y;
515:     const { dmg, crit } = this.skillDamage(skill);
516:     this.hitMonster(target, dmg, { crit, skill });
517:     this.empowered = 1;
518:     this.addEffect({ kind: 'burst', x: this.player.x, y: this.player.y - 30, color: skill.color, life: 0.5, maxLife: 0.5 });
519:     this.applyLifesteal(dmg);
520:   }
521: 
522:   applyLifesteal(dmg) {
523:     const ls = this.player.stats.lifesteal;
524:     if (ls > 0) {
525:       const heal = dmg * ls;
526:       if (heal > 1) this.player.hp = Math.min(this.player.stats.maxHp, this.player.hp + heal);
527:     }
528:   }
529: 
530:   hitMonster(mon, raw, opts = {}) {
531:     if (!mon || mon.dead) return;
532:     const red = mon.defense / (mon.defense + 95 + mon.level * 8);
533:     let dmg = Math.max(1, Math.round(raw * (1 - red)));
534:     if (this.armorBuffUntil > 0) dmg = Math.round(dmg * 1.04);
535:     mon.hp -= dmg;
536:     mon.flash = 0.12;
537:     mon.aggro = true;
538:     mon.lastHit = this.time;
539:     if (!mon.boss) mon.state = 'chase';
540:     this.hitCombo++;
541:     this.comboTimer = 1.6;
542:     this.floater(mon.x + (Math.random() - 0.5) * 16, mon.y - 64 - (mon.scale - 1) * 20, `${dmg}${opts.crit ? '!' : ''}`, opts.crit ? '#ffd76e' : opts.skill ? opts.skill.color : '#f0e6d0', opts.crit ? 1.35 : 1);
543:     if (opts.crit) {
544:       this.addEffect({ kind: 'crit', x: mon.x, y: mon.y - 40, color: '#ffd76e', life: 0.4, maxLife: 0.4 });
545:       this.sfx('crit');
546:     }
547:     this.addEffect({ kind: 'impact', x: mon.x, y: mon.y - 28, color: opts.skill?.color ?? '#ffcf8a', life: 0.3, maxLife: 0.3 });
548:     if (mon.hp <= 0) this.killMonster(mon);
549:     else this.sfx('hit');
550:   }
551: 
552:   killMonster(mon) {
553:     if (mon.dead) return;
554:     mon.dead = true;
555:     mon.hp = 0;
556:     mon.respawnAt = this.time + (mon.boss ? 95 : mon.elite ? 55 : 28);
557:     mon.aggro = false;
558:     this.player.kills = (this.player.kills ?? 0) + 1;
559:     if (mon.boss) {
560:       this.player.bossKills = (this.player.bossKills ?? 0) + 1;
561:       this.bossEngaged = false;
562:       this.bossWarned = false;
563:       this.bossSlamTimer = 4;
564:     }
565:     if (this.targetUid === mon.uid) this.targetUid = null;
566:     const xpGain = mon.xp * (this.xpBuffUntil > Date.now() ? 1.25 : 1);
567:     const res = addXP(this.player, xpGain);
568:     this.floater(mon.x, mon.y - 82, `+${Math.round(xpGain)} XP`, '#b9d6ff', 0.95);
569:     if (res.levels > 0) {
570:       this.addEffect({ kind: 'levelup', x: this.player.x, y: this.player.y, color: '#f4e3b0', life: 1.6, maxLife: 1.6 });
571:       this.notify(t('hud.levelUp') + ' ' + t('hud.levelUpText', { lv: this.player.level }), 'good');
572:       this.sfx('levelup');
573:       this.game.flashLevel = this.time;
574:       this.save();
575:     }
576:     // drops
577:     const goldAmount = Math.round(mon.gold * (1 + this.player.stats.goldFind));
578:     this.spawnLoot({ type: 'gold', x: mon.x + (Math.random() - 0.5) * 22, y: mon.y + 4, amount: goldAmount, color: '#d9b76a' });
579:     const itemChance = mon.boss ? 1 : mon.elite ? 0.95 : 0.68;
580:     if (Math.random() < itemChance) {
581:       const rarity = weighted(Math.random, DROP_WEIGHTS);
582:       const level = clamp(this.zone.min + Math.floor(Math.random() * 4), 1, 60);
583:       const classId = Math.random() < 0.82 ? this.player.classId : ['warrior', 'mage', 'assassin'][Math.floor(Math.random() * 3)];
584:       const slots = ['weapon', 'offhand', 'helm', 'chest', 'gloves', 'boots', 'belt', 'ring', 'amulet'];
585:       const slot = slots[Math.floor(Math.random() * slots.length)];
586:       const item = makeEquip({ classId, slot, rarity, tier: 'T3', level });
587:       this.spawnLoot({ type: 'item', x: mon.x + (Math.random() - 0.5) * 30, y: mon.y + 2, item, color: RARITY[rarity].color });
588:     }
589:     if (Math.random() < (mon.boss ? 1 : mon.elite ? 0.22 : 0.045)) {
590:       this.spawnLoot({ type: 'gem', x: mon.x + (Math.random() - 0.5) * 26, y: mon.y + 6, amount: 1 + (mon.boss ? 3 : 0), color: '#8fd8ee' });
591:     }
592:     if (mon.boss) {
593:       const stone = makeBossStone(this.zone.id, this.zone.boss.stoneName);
594:       this.spawnLoot({ type: 'stone', x: mon.x + 10, y: mon.y, item: stone, color: '#f4e3b0' });
595:       if (!this.player.bossFirstKills[this.zone.id]) {
596:         this.player.bossFirstKills[this.zone.id] = true;
597:         addGems(this.player, 20);
598:         this.floater(mon.x, mon.y - 110, '+20 Gems', '#8fd8ee', 1.1, 1.4);
599:       }
600:       this.notify(`${tx(mon.name)} — ${t('combat.victory')}`, 'good');
601:     }
602:     // quests
603:     const done = advanceQuests(this.player, 'kill', mon.defId, 1);
604:     if (mon.elite) advanceQuests(this.player, 'killElite', mon.defId, 1).forEach((q) => done.push(q));
605:     if (mon.boss) advanceQuests(this.player, 'boss', mon.defId, 1).forEach((q) => done.push(q));
606:     for (const q of done) {
607:       this.notify(t('quest.completeToast', { name: tx(q.name) }), 'good');
608:       this.sfx('quest');
609:     }
610:     this.addEffect({ kind: 'soul', x: mon.x, y: mon.y - 30, color: mon.boss ? '#ffcf8a' : '#b9d6ff', life: 0.9, maxLife: 0.9, scale: mon.scale });
611:     this.save();
612:   }
613: 
614:   damagePlayer(amount, source) {
615:     if (this.dead || this.time < (this.invulnUntil ?? 0)) return;
616:     const red = this.player.stats.armor / (this.player.stats.armor + 92 + this.player.level * 9);
617:     let dmg = Math.max(1, Math.round(amount * (1 - red) * 0.9));
618:     this.player.hp -= dmg;
619:     this.damageFlash = 1;
620:     this.floater(this.player.x + (Math.random() - 0.5) * 14, this.player.y - 70, `-${dmg}`, '#ff8a80', 1.05);
621:     this.addEffect({ kind: 'impact', x: this.player.x, y: this.player.y - 30, color: '#ff6b63', life: 0.3, maxLife: 0.3 });
622:     this.shakeTime = Math.max(this.shakeTime, 0.22);
623:     this.sfx('hurt');
624:     if (this.player.mount) this.player.mount = null;
625:     if (this.player.hp <= 0) { this.player.hp = 0; this.die(); }
626:   }
627: 
628:   die() {
629:     this.dead = true;
630:     this.targetUid = null;
631:     this.attackHeld = false;
632:     this.channel = null;
633:     this.sfx('death');
634:     this.save(true);
635:     App.ui?.onDeath?.();
636:   }
637: 
638:   respawn() {
639:     const camp = this.data.camp;
640:     this.player.hp = Math.round(this.player.stats.maxHp * 0.6);
641:     this.player.resource = Math.round(this.player.stats.maxResource * 0.4);
642:     this.player.x = camp.x;
643:     this.player.y = camp.y + 40;
644:     this.camera.x = this.player.x; this.camera.y = this.player.y;
645:     this.dead = false;
646:     this.invulnUntil = this.time + 2.5;
647:     this.targetUid = null;
648:     for (const m of this.monsters) {
649:       if (!m.boss) { m.aggro = false; m.x = m.homeX; m.y = m.homeY; m.state = 'idle'; }
650:     }
651:     this.save();
652:   }
653: 
654:   gainResource(amount) {
655:     this.player.resource = Math.min(this.player.stats.maxResource, this.player.resource + amount);
656:   }
657: 
658:   usePotion() {
659:     if (this.player.hp >= this.player.stats.maxHp * 0.999) { this.notify(t('toast.potionFull')); return false; }
660:     const potion = this.player.inventory.find((i) => i.kind === 'consumable' && i.id === 'healPotion' && (i.qty ?? 0) > 0);
661:     if (!potion) { this.notify(t('common.empty'), 'bad'); return false; }
662:     const heal = this.player.stats.maxHp * 0.45;
663:     this.player.hp = Math.min(this.player.stats.maxHp, this.player.hp + heal);
664:     if ((potion.qty ?? 1) > 1) potion.qty--; else this.player.inventory.splice(this.player.inventory.indexOf(potion), 1);
665:     this.floater(this.player.x, this.player.y - 72, `+${Math.round(heal)}`, '#8ce07a', 1.1);
666:     this.addEffect({ kind: 'pillar', x: this.player.x, y: this.player.y, color: '#8ce07a', life: 0.7, maxLife: 0.7 });
667:     this.sfx('heal');
668:     this.save();
669:     return true;
670:   }
