678:       p.hp = Math.min(p.stats.maxHp, p.hp + p.stats.maxHp * (item.heal ?? 0.45));
679:       this.floater(p.x, p.y - 70, `+${Math.round(p.stats.maxHp * (item.heal ?? 0.45))}`, '#8ce07a');
680:     } else if (item.id === 'manaPotion') {
681:       p.resource = Math.min(p.stats.maxResource, p.resource + p.stats.maxResource * (item.resource ?? 0.45));
682:       this.floater(p.x, p.y - 70, `+${Math.round(p.stats.maxResource * (item.resource ?? 0.45))}`, '#8fd8ee');
683:     } else if (item.id === 'elixir') {
684:       this.xpBuffUntil = Date.now() + 30 * 60000;
685:       this.notify('+25% XP (30m)', 'good');
686:     } else if (item.id === 'charm') {
687:       this.gatherBuffUntil = Date.now() + 30 * 60000;
688:       this.notify('+25% ' + t('char.gatherSpeed') + ' (30m)', 'good');
689:     } else if (item.id === 'moonbread') {
690:       p.hp = Math.min(p.stats.maxHp, p.hp + p.stats.maxHp * 0.3);
691:       p.resource = Math.min(p.stats.maxResource, p.resource + p.stats.maxResource * 0.3);
692:     }
693:     if ((item.qty ?? 1) > 1) item.qty--; else {
694:       const idx = p.inventory.indexOf(item);
695:       if (idx >= 0) p.inventory.splice(idx, 1);
