720:   // ── monsters ────────────────────────────────────────────────────────────
721:   updateMonsters(dt) {
722:     const p = this.player;
723:     for (const m of this.monsters) {
724:       if (m.dead) {
725:         if (this.time >= m.respawnAt && this.time > 0) {
726:           m.dead = false; m.hp = m.maxHp; m.x = m.homeX; m.y = m.homeY; m.aggro = false; m.state = 'idle'; m.stunUntil = 0; m.slowUntil = 0; m.poisonUntil = 0; m.burnUntil = 0;
727:         }
728:         continue;
729:       }
730:       m.anim += dt;
731:       m.flash = Math.max(0, m.flash - dt);
732:       // status effects
733:       if (m.poisonUntil > this.time) {
734:         m.poisonTick += dt;
735:         if (m.poisonTick >= 1) {
736:           m.poisonTick = 0;
737:           const dmg = Math.max(1, Math.round(this.player.stats.attack * 0.16));
738:           m.hp -= dmg;
739:           this.floater(m.x, m.y - 60, `${dmg}`, '#8ce07a', 0.9);
740:           if (m.hp <= 0) { this.killMonster(m); continue; }
741:         }
742:       }
743:       if (m.burnUntil > this.time) {
744:         m.burnTick += dt;
745:         if (m.burnTick >= 0.8) {
746:           m.burnTick = 0;
747:           const dmg = Math.max(1, Math.round(this.player.stats.attack * 0.12));
748:           m.hp -= dmg;
749:           this.floater(m.x, m.y - 58, `${dmg}`, '#ff9a5c', 0.9);
750:           if (m.hp <= 0) { this.killMonster(m); continue; }
751:         }
752:       }
753:       if (m.stunUntil > this.time) continue;
754:       const dToPlayer = dist(m.x, m.y, p.x, p.y);
755:       const aggroRange = m.boss ? 360 : m.elite ? 270 : 200;
756:       const leash = m.boss ? 460 : 500;
757:       if (this.dead) m.aggro = false;
758:       if (!m.aggro && dToPlayer < aggroRange && !this.dead) {
759:         m.aggro = true;
760:         if (m.boss && !this.bossWarned) {
761:           this.bossWarned = true;
762:           this.bossEngaged = true;
763:           this.notify(t('combat.bossWarning', { name: tx(m.name) }), 'bad');
764:           this.sfx('boss');
765:         } else if (m.elite) {
766:           this.notify(t('combat.eliteWarning'), 'bad');
767:         }
768:       }
769:       const homeDist = dist(m.x, m.y, m.homeX, m.homeY);
770:       if (m.aggro && homeDist > leash) {
771:         m.aggro = false;
772:         m.state = 'return';
773:       }
774:       const slowMul = m.slowUntil > this.time ? 0.45 : 1;
775:       const baseSpeed = m.boss ? 68 : m.elite ? 86 : 78;
776:       const speed = baseSpeed * slowMul * (m.boss ? 1 : m.scale * 0.9);
777:       if (m.aggro) {
778:         const range = (m.boss ? 78 : 46) + m.scale * 6;
779:         if (dToPlayer > range) {
780:           const a = Math.atan2(p.y - m.y, p.x - m.x);
781:           let nx = m.x + Math.cos(a) * speed * dt;
782:           let ny = m.y + Math.sin(a) * speed * dt;
783:           // avoid stacking
784:           const r = resolveCollision(nx, ny, this.data.props);
785:           m.x = r.x; m.y = r.y;
786:           m.facing = p.x >= m.x ? 1 : -1;
787:           m.state = 'chase';
788:         } else {
789:           m.state = 'attack';
790:           m.attackCd -= dt;
791:           if (m.attackCd <= 0) {
792:             m.attackCd = m.boss ? 1.35 : m.elite ? 1.5 : 1.7;
793:             const dmg = m.attack * (0.9 + Math.random() * 0.2) * (m.boss ? 1.15 : 1);
794:             this.damagePlayer(dmg, m);
795:             this.addEffect({ kind: 'enemySlash', x: m.x, y: m.y - 30, tx: p.x, ty: p.y - 30, color: '#ff8a6a', life: 0.28, maxLife: 0.28 });
796:             this.sfx('enemy');
797:           }
798:         }
799:         if (m.boss) this.updateBoss(dt, m);
800:       } else if (m.state === 'return' && homeDist > 30) {
801:         const a = Math.atan2(m.homeY - m.y, m.homeX - m.x);
802:         m.x += Math.cos(a) * speed * 1.2 * dt;
803:         m.y += Math.sin(a) * speed * 1.2 * dt;
804:         if (homeDist < 40) { m.state = 'idle'; m.hp = Math.min(m.maxHp, m.hp + m.maxHp * 0.3); }
805:       } else {
806:         // wander
807:         m.wanderTimer -= dt;
808:         if (m.wanderTimer <= 0) { m.wanderTimer = 2 + Math.random() * 4; m.wanderAngle = Math.random() * TAU; }
809:         if (Math.random() < 0.5) {
810:           const nx = m.x + Math.cos(m.wanderAngle) * 16 * dt;
811:           const ny = m.y + Math.sin(m.wanderAngle) * 16 * dt;
812:           if (dist(nx, ny, m.homeX, m.homeY) < 120) { const r = resolveCollision(nx, ny, this.data.props); m.x = r.x; m.y = r.y; }
813:           m.facing = Math.cos(m.wanderAngle) >= 0 ? 1 : -1;
814:         }
815:         m.state = 'idle';
816:       }
817:       if (!m.boss && m.aggro && dToPlayer < 300 && Math.random() < 0.02) {
818:         this.addEffect({ kind: 'aggro', x: m.x, y: m.y - 64, color: '#ff9a6a', life: 0.5, maxLife: 0.5 });
819:       }
820:       m.x = clamp(m.x, 40, WORLD_SIZE - 40);
821:       m.y = clamp(m.y, 40, WORLD_SIZE - 40);
822:     }
823:   }
