855:       l.born += dt;
856:       const d = dist(l.x, l.y, p.x, p.y);
857:       if ((l.type === 'gold' || l.type === 'gem') && d < 220) {
858:         const a = Math.atan2(p.y - l.y, p.x - l.x);
859:         const sp = 160 + (220 - d) * 1.6;
860:         l.x += Math.cos(a) * sp * dt;
861:         l.y += Math.sin(a) * sp * dt;
862:       }
863:       if (l.born > l.pickupDelay && d < 42) this.collectLoot(l);
864:     }
865:     this.loot = this.loot.filter((l) => !l.collected);
