916:       const d = dist(p.x, p.y, npc.x, npc.y);
917:       if (d < bd) { bd = d; best = { kind: 'npc', ref: npc, label: t('npc.talkTo', { name: t(npc.nameKey) }), icon: 'talk' }; }
918:     }
919:     const portal = this.data.portal;
920:     const pd = dist(p.x, p.y, portal.x, portal.y);
921:     if (pd < 95 && pd < bd) { bd = pd; best = { kind: 'portal', ref: portal, label: tx(portal.label), icon: 'portal' }; }
922:     for (const node of this.nodes) {
923:       if (!node.ready) continue;
924:       const d = dist(p.x, p.y, node.x, node.y);
925:       if (d < 62 && d < bd) { bd = d; best = { kind: 'node', ref: node, label: `${t('common.gather')} · ${t(`gather.${node.type}`)}`, icon: 'herb' }; }
926:     }
927:     this.interaction = best;
