1005:   // ── render ──────────────────────────────────────────────────────────────
1006:   render(dt) {
1007:     const ctx = this.ctx;
1008:     if (!this.data) return;
1009:     const scale = this.w / VIEW_W;
1010:     const viewH = this.h / scale;
1011:     const camX = this.camera.x, camY = this.camera.y;
1012:     let shakeX = 0, shakeY = 0;
1013:     if (this.shakeTime > 0) {
1014:       shakeX = (Math.random() - 0.5) * 8 * Math.min(1, this.shakeTime * 4);
1015:       shakeY = (Math.random() - 0.5) * 8 * Math.min(1, this.shakeTime * 4);
1016:     }
1017:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
1018:     ctx.fillStyle = '#050508';
1019:     ctx.fillRect(0, 0, this.w, this.h);
1020:     ctx.save();
1021:     ctx.scale(scale, scale);
1022:     ctx.translate(VIEW_W / 2 - camX + shakeX / scale, viewH / 2 - camY + shakeY / scale);
1023: 
1024:     // terrain
1025:     ctx.drawImage(this.data.terrain, 0, 0, WORLD_SIZE, WORLD_SIZE);
1026: 
1027:     // ground ambient light pools
1028:     const zone = this.zone;
1029:     ctx.save();
1030:     const amb = ctx.createRadialGradient(this.player.x, this.player.y, 50, this.player.x, this.player.y, 380);
1031:     amb.addColorStop(0, hexA(zone.palette.light, 0.04)); amb.addColorStop(1, 'rgba(0,0,0,0)');
1032:     ctx.fillStyle = amb; ctx.fillRect(this.player.x - 400, this.player.y - 400, 800, 800);
1033:     ctx.restore();
1034: 
1035:     // ground effects (telegraphs, rings)
1036:     for (const e of this.effects) {
1037:       if (e.kind === 'telegraph') this.drawTelegraph(e);
1038:     }
1039:     if (this.channel) this.drawChannelRing();
1040: 
1041:     // renderables sorted by feet Y
1042:     const renderables = [];
1043:     for (const prop of this.data.props) {
1044:       renderables.push({ y: prop.y, draw: () => this.drawProp(prop) });
1045:     }
1046:     for (const d of this.data.decorations) renderables.push({ y: d.y, draw: () => art.drawDecoration(ctx, d, this.time) });
1047:     for (const npc of this.npcs ?? []) renderables.push({ y: npc.y, draw: () => art.drawNPC(ctx, npc, this.time) });
1048:     renderables.push({ y: this.data.portal.y, draw: () => art.drawPortal(ctx, this.data.portal, this.time, zone.camp) });
1049:     for (const node of this.nodes) renderables.push({ y: node.y, draw: () => art.drawGatherNode(ctx, node, this.time) });
1050:     for (const l of this.loot) renderables.push({ y: l.y, draw: () => art.drawLoot(ctx, l, this.time) });
1051:     for (const m of this.monsters) {
1052:       if (m.dead) continue;
1053:       renderables.push({ y: m.y, draw: () => this.drawMonster(m) });
1054:     }
1055:     renderables.push({ y: this.player.y, draw: () => {
1056:       art.drawWorldHero(ctx, this.player, this.player.x, this.player.y, this.time, {
1057:         moving: this.moving, facing: this.facing, attackAnim: this.attackAnim, combatGlow: this.inCombat(),
1058:       });
1059:       if (this.interaction) art.drawInteractRing(ctx, this.interaction.ref.x, this.interaction.ref.y, this.time);
1060:     } });
1061:     renderables.sort((a, b) => a.y - b.y);
1062:     for (const r of renderables) r.draw();
1063: 
1064:     // effects above ground
1065:     for (const e of this.effects) {
1066:       if (e.kind !== 'telegraph') this.drawEffect(e);
1067:     }
1068:     // projectiles
1069:     for (const pr of this.projectiles) {
1070:       ctx.save(); ctx.globalCompositeOperation = 'lighter';
1071:       const g = ctx.createRadialGradient(pr.x, pr.y, 1, pr.x, pr.y, 14);
1072:       g.addColorStop(0, '#ffffff'); g.addColorStop(0.4, hexA(pr.color, 0.8)); g.addColorStop(1, hexA(pr.color, 0));
1073:       ctx.fillStyle = g; ctx.beginPath(); ctx.arc(pr.x, pr.y, 14, 0, TAU); ctx.fill();
1074:       ctx.restore();
1075:     }
1076:     // floaters
1077:     for (const f of this.floaters) {
1078:       const a = Math.min(1, f.life / 0.3);
1079:       ctx.save(); ctx.globalAlpha = a;
1080:       ctx.font = `700 ${Math.round(11 * f.scale)}px Inter, sans-serif`;
