      ctx.strokeStyle = 'rgba(240,180,140,.25)'; ctx.lineWidth = 1; ctx.stroke();
    }
  }
  // weapon effect
  if (player.fx) {
    const fxColor = player.fx === 'fx_frost' ? '#9fe8ff' : player.fx === 'fx_void' ? '#c08cf0' : '#ff8a5c';
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 7; i++) {
