// Procedural audio for AETHERIA. No external assets, no network requests.
// The tiny WebAudio synth keeps the installable build self-contained while
// still giving every weapon, spell, pickup and UI tap its own texture.

export class AudioEngine {
  constructor(settings) {
    this.settings = settings ?? { music: true, sfx: true };
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.drone = null;
    this.started = false;
    this.lastPlay = 0;
    this.unlock = this.unlock.bind(this);
  }

  setSettings(settings) {
    this.settings = settings;
    if (this.musicGain) this.musicGain.gain.value = settings.music ? 0.14 : 0;
    if (this.sfxGain) this.sfxGain.gain.value = settings.sfx ? 0.34 : 0;
    if (settings.music && this.ctx && !this.drone) this.startMusic();
    if (!settings.music && this.drone) this.stopMusic();
  }

  unlock() {
    this.ensure();
    if (!this.started) {
      this.started = true;
      if (this.settings.music) this.startMusic();
    }
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return this.ctx;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.8;
    this.master.connect(this.ctx.destination);
    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = this.settings.music ? 0.14 : 0;
    this.musicGain.connect(this.master);
    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = this.settings.sfx ? 0.34 : 0;
    this.sfxGain.connect(this.master);
    return this.ctx;
  }

  startMusic() {
    const ctx = this.ensure();
    if (!ctx || this.drone) return;
    const bus = ctx.createGain();
    bus.gain.value = 0;
    bus.gain.linearRampToValueAtTime(0.72, ctx.currentTime + 7);
    bus.connect(this.musicGain);
    const notes = [55, 82.41, 110, 164.81, 220];
    const oscs = [];
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      const filter = ctx.createBiquadFilter();
      osc.type = i % 2 ? 'triangle' : 'sine';
      osc.frequency.value = freq;
      osc.detune.value = (i - 2) * 4;
      filter.type = 'lowpass';
      filter.frequency.value = 500 + i * 110;
      filter.Q.value = 0.5;
      gain.gain.value = i === 0 ? 0.18 : 0.06 / (i * 0.5);
      osc.connect(filter);
      filter.connect(gain);
      gain.connect(bus);
      osc.start();
      oscs.push(osc);
    });
    // Slow breathing filter gives the pad a living, wind-like motion.
    const lfo = ctx.createOscillator();
    const lfoGain = ctx.createGain();
    lfo.frequency.value = 0.045;
    lfoGain.gain.value = 170;
    lfo.connect(lfoGain);
    lfoGain.connect(oscs[1]?.frequency ?? oscs[0].frequency);
    lfo.start();
    this.drone = { bus, oscs, lfo };
  }

  stopMusic() {
    if (!this.drone || !this.ctx) return;
    const { bus, oscs, lfo } = this.drone;
    const now = this.ctx.currentTime;
    bus.gain.cancelScheduledValues(now);
    bus.gain.setValueAtTime(bus.gain.value, now);
    bus.gain.linearRampToValueAtTime(0, now + 1.2);
    setTimeout(() => {
      try { bus.disconnect(); } catch {}
      for (const o of oscs) { try { o.stop(); } catch {} }
      try { lfo.stop(); } catch {}
    }, 1400);
    this.drone = null;
  }

  tone(freq, dur, opts = {}) {
    const ctx = this.ensure();
    if (!ctx) return;
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const filter = ctx.createBiquadFilter();
    osc.type = opts.type ?? 'sine';
    osc.frequency.setValueAtTime(freq, now);
    if (opts.slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, opts.slide), now + dur);
    filter.type = opts.filter ?? 'lowpass';
    filter.frequency.value = opts.cutoff ?? 2600;
    filter.Q.value = opts.q ?? 0.8;
    const vol = Math.max(0.001, opts.vol ?? 0.12);
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(vol, now + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + dur);
    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.sfxGain);
    osc.start(now);
    osc.stop(now + dur + 0.04);
  }

  noise(dur, opts = {}) {
    const ctx = this.ensure();
    if (!ctx) return;
    const now = ctx.currentTime;
    const frames = Math.max(1, Math.floor(ctx.sampleRate * dur));
    const buffer = ctx.createBuffer(1, frames, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < frames; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / frames);
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = opts.filter ?? 'bandpass';
    filter.frequency.value = opts.freq ?? 1200;
    filter.Q.value = opts.q ?? 1;
    const gain = ctx.createGain();
    gain.gain.value = opts.vol ?? 0.09;
    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.sfxGain);
    src.start(now);
  }

  play(name) {
    if (!this.settings.sfx) return;
    const ctx = this.ensure();
    if (!ctx) return;
    const now = performance.now();
    if (now - this.lastPlay < 24) return;
    this.lastPlay = now;
    switch (name) {
      case 'slash':
        this.noise(0.1, { freq: 2100, q: 0.7, vol: 0.1 });
        this.tone(190, 0.09, { type: 'triangle', slide: 110, vol: 0.045 });
        break;
      case 'cast':
        this.tone(720, 0.22, { type: 'sine', slide: 1240, vol: 0.06 });
        this.tone(1080, 0.16, { type: 'triangle', slide: 1640, vol: 0.025 });
        break;
      case 'hit':
        this.noise(0.07, { freq: 900, q: 0.6, vol: 0.07 });
        this.tone(130, 0.06, { type: 'square', slide: 80, vol: 0.035 });
        break;
      case 'crit':
        this.tone(880, 0.12, { type: 'triangle', slide: 1400, vol: 0.07 });
        this.noise(0.12, { freq: 2600, q: 0.8, vol: 0.05 });
        break;
      case 'enemy':
        this.noise(0.12, { freq: 620, q: 0.5, vol: 0.06 });
        this.tone(96, 0.13, { type: 'sawtooth', slide: 62, vol: 0.035 });
        break;
      case 'hurt':
        this.tone(145, 0.2, { type: 'sawtooth', slide: 70, vol: 0.08 });
        this.noise(0.16, { freq: 480, q: 0.4, vol: 0.055 });
        break;
      case 'coin':
        this.tone(1320, 0.08, { type: 'triangle', vol: 0.045 });
        setTimeout(() => this.tone(1760, 0.11, { type: 'triangle', vol: 0.04 }), 55);
        break;
      case 'gem':
        this.tone(1175, 0.1, { type: 'sine', vol: 0.055 });
        setTimeout(() => this.tone(1568, 0.18, { type: 'sine', vol: 0.05 }), 70);
        break;
      case 'loot':
        this.tone(540, 0.08, { type: 'triangle', vol: 0.04 });
        setTimeout(() => this.tone(810, 0.14, { type: 'triangle', vol: 0.035 }), 65);
        break;
      case 'gather':
        this.noise(0.15, { freq: 520, q: 0.6, vol: 0.04 });
        break;
      case 'gatherDone':
        this.tone(440, 0.12, { type: 'sine', vol: 0.05 });
        setTimeout(() => this.tone(660, 0.16, { type: 'sine', vol: 0.04 }), 100);
        break;
      case 'heal':
        [523, 659, 784].forEach((f, i) => setTimeout(() => this.tone(f, 0.2, { type: 'sine', vol: 0.04 }), i * 70));
        break;
      case 'levelup':
        [392, 523, 659, 784].forEach((f, i) => setTimeout(() => this.tone(f, 0.28, { type: 'triangle', vol: 0.055 }), i * 100));
        break;
      case 'quest':
        [660, 880].forEach((f, i) => setTimeout(() => this.tone(f, 0.18, { type: 'sine', vol: 0.045 }), i * 110));
        break;
      case 'mount':
        this.tone(220, 0.2, { type: 'triangle', slide: 330, vol: 0.055 });
        this.noise(0.2, { freq: 800, q: 0.5, vol: 0.03 });
        break;
      case 'boss':
        this.tone(68, 0.8, { type: 'sawtooth', vol: 0.08 });
        setTimeout(() => this.tone(52, 1.1, { type: 'sawtooth', vol: 0.06 }), 170);
        break;
      case 'bossCast':
        this.tone(160, 0.5, { type: 'sawtooth', slide: 60, vol: 0.06 });
        break;
      case 'stone':
        [784, 1046, 1318].forEach((f, i) => setTimeout(() => this.tone(f, 0.22, { type: 'sine', vol: 0.045 }), i * 80));
        break;
      case 'death':
        this.tone(180, 0.9, { type: 'sawtooth', slide: 45, vol: 0.1 });
        break;
      case 'ui':
        this.tone(680, 0.04, { type: 'triangle', vol: 0.02 });
        break;
      default:
        this.tone(520, 0.06, { type: 'triangle', vol: 0.03 });
    }
  }
}

// Minimal real transport seam for AETHERIA multiplayer.
// This client never simulates other players: everything shown in the trade
// panel comes from a WebSocket server. The bundled server in /server is a
// development reference implementation of that protocol.

export class TradeClient {
  constructor() {
    this.ws = null;
    this.url = null;
    this.state = 'offline';
    this.identity = null;
    this.players = [];
    this.handlers = new Map();
    this.queued = [];
  }

  on(event, fn) {
    if (!this.handlers.has(event)) this.handlers.set(event, new Set());
    this.handlers.get(event).add(fn);
    return () => this.handlers.get(event)?.delete(fn);
  }

  emit(event, payload) {
    for (const fn of this.handlers.get(event) ?? []) {
      try { fn(payload); } catch (error) { console.warn('TradeClient handler failed', error); }
    }
  }

  connect(url, identity) {
    this.disconnect();
    this.url = url;
    this.identity = identity;
    this.state = 'connecting';
    this.emit('state', { state: 'connecting', url });
    return new Promise((resolve, reject) => {
      let ws;
      try { ws = new WebSocket(url); } catch (error) {
        this.state = 'offline';
        this.emit('state', { state: 'offline', error: String(error?.message ?? error) });
        reject(error);
        return;
      }
      this.ws = ws;
      const timeout = setTimeout(() => {
        if (this.state !== 'connecting') return;
        try { ws.close(); } catch {}
        this.state = 'offline';
        this.emit('state', { state: 'offline', error: 'Connection timed out.' });
        reject(new Error('Connection timed out.'));
      }, 7000);

      ws.addEventListener('open', () => {
        clearTimeout(timeout);
        this.state = 'online';
        this.emit('state', { state: 'online', url });
        this.send('hello', identity);
        for (const message of this.queued.splice(0)) this.send(message.type, message.payload);
        resolve(true);
      });
      ws.addEventListener('message', (event) => {
        let msg;
        try { msg = JSON.parse(event.data); } catch { return; }
        if (!msg || typeof msg.type !== 'string') return;
        if (msg.type === 'presence') this.players = msg.players ?? [];
        if (msg.type === 'welcome') this.identity = { ...this.identity, ...msg.you };
        this.emit(msg.type, msg);
        this.emit('message', msg);
      });
      ws.addEventListener('close', () => {
        clearTimeout(timeout);
        this.state = 'offline';
        this.ws = null;
        this.players = [];
        this.emit('state', { state: 'offline', url });
      });
      ws.addEventListener('error', () => {
        // The close handler is the single source of truth; surface a readable
        // error without rejecting twice.
        this.emit('state', { state: 'error', url, error: 'Server unreachable.' });
      });
    });
  }

  disconnect() {
    if (this.ws) {
      try { this.ws.close(); } catch {}
    }
    this.ws = null;
    this.state = 'offline';
    this.players = [];
  }

  send(type, payload = {}) {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
      this.queued.push({ type, payload });
      return false;
    }
    this.ws.send(JSON.stringify({ type, ...payload }));
    return true;
  }

  updateIdentity(identity) {
    this.identity = identity;
    if (this.state === 'online') this.send('hello', identity);
  }
}

/* ============ AETHERIA — shared game UI ============ */
:root{
  --panel-radius:3px;
}

/* ---------- screen / overlay helpers ---------- */
#screen{isolation:isolate;}
#overlay{isolation:isolate;}
.fade-in{animation:fadeIn .22s var(--ease) both;}
.slide-up{animation:slideUp .3s var(--ease) both;}
@keyframes slideUp{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}

/* ---------- HUD ---------- */
.game-screen{position:absolute;inset:0;background:#050508;overflow:hidden;}
#worldCanvas{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none;}
.hud{position:absolute;inset:0;pointer-events:none;z-index:10;font-size:12px;}
.hud button,.hud input,.hud .tap{pointer-events:auto;}
.hud-top{position:absolute;top:0;left:0;right:0;padding:calc(8px + var(--safe-top)) 10px 0;display:flex;justify-content:space-between;align-items:flex-start;gap:8px;}
.hero-hud{display:flex;gap:8px;align-items:center;min-width:0;filter:drop-shadow(0 2px 5px rgba(0,0,0,.6));}
.hero-avatar{width:42px;height:42px;flex:none;border:1px solid rgba(217,183,106,.5);background:radial-gradient(circle at 40% 30%,rgba(64,55,38,.9),rgba(8,9,13,.95));display:grid;place-items:center;color:var(--gold-hi);position:relative;}
.hero-avatar::after{content:"";position:absolute;inset:3px;border:1px solid rgba(217,183,106,.15);}
.hero-avatar svg{width:23px;height:23px;}
.hero-hud-info{min-width:0;flex:1;}
.hero-name-line{display:flex;align-items:baseline;gap:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.hero-name-line b{font-family:var(--font-display);font-size:12px;letter-spacing:.05em;color:#f0e7d4;max-width:120px;overflow:hidden;text-overflow:ellipsis;}
.hero-name-line span{font-size:9px;color:var(--gold);letter-spacing:.08em;text-transform:uppercase;white-space:nowrap;}
.bar{position:relative;height:8px;background:rgba(0,0,0,.66);border:1px solid rgba(255,255,255,.12);overflow:hidden;border-radius:1px;}
.bar>i{display:block;height:100%;transition:width .18s linear;}
.bar.hp>i{background:linear-gradient(90deg,#7d2c2b,#cf5147 55%,#e97d64);}
.bar.res>i{background:linear-gradient(90deg,#2f5a83,#579bd0 55%,#89d3ee);}
.bar.xp{height:4px;border-color:rgba(217,183,106,.18);background:rgba(0,0,0,.55);}
.bar.xp>i{background:linear-gradient(90deg,#8a6c36,#d9b76a,#f4e3b0);}
.hero-bars{display:flex;flex-direction:column;gap:3px;margin-top:3px;width:min(38vw,176px);}
.bar .bar-label{position:absolute;inset:0;display:flex;justify-content:space-between;padding:0 4px;font-size:7.5px;line-height:8px;font-weight:600;letter-spacing:.03em;color:rgba(255,255,255,.92);text-shadow:0 1px 2px #000;}
.hero-xp{margin-top:3px;width:min(38vw,176px);}
.top-right{display:flex;flex-direction:column;align-items:flex-end;gap:5px;}
.currency-row{display:flex;gap:5px;align-items:center;}
.currency{display:flex;align-items:center;gap:3px;height:23px;padding:0 7px;background:rgba(7,8,13,.72);border:1px solid rgba(217,183,106,.26);font-size:9.5px;font-weight:600;letter-spacing:.03em;color:#eadfc5;backdrop-filter:blur(5px);}
.currency svg{width:13px;height:13px;}
.currency.gold svg{color:#e8c26f;}
.currency.gems svg{color:#8fd8ee;}
.minimap-wrap{position:absolute;right:10px;top:calc(72px + var(--safe-top));width:92px;height:66px;border:1px solid rgba(217,183,106,.28);box-shadow:0 5px 18px rgba(0,0,0,.55);background:rgba(7,8,12,.6);overflow:hidden;}
#minimap{width:100%;height:100%;display:block;}
.minimap-wrap .zone-mini{position:absolute;left:0;right:0;bottom:0;padding:2px 4px;background:linear-gradient(transparent,rgba(4,5,8,.88));font-size:6.5px;color:#d7c7a2;text-transform:uppercase;letter-spacing:.11em;text-align:center;pointer-events:none;}
.zone-hud{position:absolute;left:50%;top:calc(9px + var(--safe-top));transform:translateX(-50%);font-family:var(--font-display);font-size:9px;letter-spacing:.19em;text-transform:uppercase;color:rgba(238,224,192,.76);text-shadow:0 2px 5px #000;white-space:nowrap;pointer-events:none;}
.zone-hud b{display:block;text-align:center;font-size:11px;letter-spacing:.14em;color:rgba(244,227,176,.95);}
.zone-hud .danger{display:block;text-align:center;font-family:var(--font-ui);font-size:7px;letter-spacing:.12em;color:#de9e70;margin-top:1px;}
.quest-track{position:absolute;left:10px;top:calc(106px + var(--safe-top));width:min(66vw,238px);padding:9px 10px 8px;background:linear-gradient(110deg,rgba(8,9,14,.82),rgba(8,9,14,.42) 75%,transparent);border-left:2px solid rgba(217,183,106,.55);pointer-events:auto;cursor:pointer;filter:drop-shadow(0 3px 8px rgba(0,0,0,.45));}
.quest-track .qt-eyebrow{font-size:7.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--gold);opacity:.9;}
.quest-track .qt-name{font-family:var(--font-display);font-size:12px;letter-spacing:.035em;color:#f1e7d1;margin-top:2px;line-height:1.25;text-shadow:0 1px 4px #000;}
.quest-track .qt-obj{display:flex;gap:6px;align-items:center;margin-top:4px;font-size:9.5px;color:#bdb5a5;line-height:1.25;}
.quest-track .qt-obj i{width:4px;height:4px;border-radius:50%;background:var(--gold-dim);flex:none;}
.quest-track .qt-obj.done{color:#86c99a;text-decoration:line-through;opacity:.65;}
.quest-track .qt-obj.done i{background:#6fbf8a;}
.quest-track .qt-ready{color:#8fe5a4;font-weight:600;}
.quest-track:empty{display:none;}

/* ---------- bottom controls ---------- */
.hud-bottom{position:absolute;left:0;right:0;bottom:0;height:230px;pointer-events:none;}
.control-cluster{position:absolute;bottom:calc(14px + var(--safe-bottom));}
.joystick{left:14px;width:124px;height:124px;touch-action:none;pointer-events:auto;opacity:.9;}
.hud.joy-right .joystick{left:auto;right:14px;}
.joy-base{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(217,183,106,.28);background:radial-gradient(circle,rgba(17,17,26,.35) 0 28%,rgba(8,9,14,.42) 62%,rgba(8,9,14,.12) 100%);box-shadow:inset 0 0 28px rgba(0,0,0,.4),0 3px 18px rgba(0,0,0,.35);backdrop-filter:blur(2px);}
.joy-base::before,.joy-base::after{content:"";position:absolute;background:rgba(217,183,106,.08);}
.joy-base::before{left:50%;top:12%;bottom:12%;width:1px;}
.joy-base::after{top:50%;left:12%;right:12%;height:1px;}
.joy-knob{position:absolute;width:50px;height:50px;left:calc(50% - 25px);top:calc(50% - 25px);border-radius:50%;border:1px solid rgba(244,227,176,.5);background:radial-gradient(circle at 38% 30%,rgba(217,183,106,.5),rgba(34,29,21,.95) 60%,rgba(12,12,16,.96));box-shadow:0 4px 14px rgba(0,0,0,.6),inset 0 0 14px rgba(244,227,176,.13);transition:transform .05s linear;display:grid;place-items:center;color:rgba(244,227,176,.6);}
.joy-knob svg{width:16px;height:16px;opacity:.75;}
.attack-cluster{right:14px;width:156px;height:158px;pointer-events:none;}
.hud.joy-right .attack-cluster{right:auto;left:14px;}
.skill-btn,.attack-btn,.utility-btn{position:absolute;pointer-events:auto;border-radius:50%;display:grid;place-items:center;touch-action:none;transition:transform .1s var(--ease);}
.skill-btn:active,.attack-btn:active,.utility-btn:active{transform:scale(.94);}
.attack-btn{right:0;bottom:8px;width:78px;height:78px;border:1px solid rgba(244,227,176,.52);background:radial-gradient(circle at 42% 30%,rgba(100,75,35,.92),rgba(40,28,15,.97) 60%,rgba(13,11,10,.98));box-shadow:0 6px 22px rgba(0,0,0,.55),inset 0 0 22px rgba(244,227,176,.12);color:#f7e9c2;}
.attack-btn svg{width:32px;height:32px;filter:drop-shadow(0 0 5px rgba(244,227,176,.2));}
.attack-btn .keycap{position:absolute;right:3px;bottom:2px;font-size:6.5px;color:rgba(244,227,176,.45);letter-spacing:.08em;}
.skill-btn{width:49px;height:49px;background:radial-gradient(circle at 38% 28%,rgba(42,42,58,.9),rgba(10,10,16,.96));border:1px solid rgba(217,183,106,.26);color:var(--skill-color,#d9b76a);box-shadow:0 3px 14px rgba(0,0,0,.5);overflow:hidden;}
.skill-btn svg{width:23px;height:23px;filter:drop-shadow(0 0 4px currentColor);}
.skill-btn .cd{position:absolute;inset:0;border-radius:50%;background:conic-gradient(rgba(2,3,6,.8) var(--cd,0%),transparent 0);pointer-events:none;}
.skill-btn .cd-num{position:absolute;inset:0;display:grid;place-items:center;font-size:12px;font-weight:700;color:#fff;text-shadow:0 1px 3px #000;pointer-events:none;}
.skill-btn.locked{opacity:.45;color:#888;border-color:rgba(255,255,255,.13);}
.skill-btn.s1{right:58px;bottom:94px;}
.skill-btn.s2{right:111px;bottom:58px;}
.skill-btn.s3{right:106px;bottom:3px;}
.hud.joy-right .skill-btn.s1{right:auto;left:58px;}
.hud.joy-right .skill-btn.s2{right:auto;left:111px;}
.hud.joy-right .skill-btn.s3{right:auto;left:106px;}
.skill-btn .skey{position:absolute;right:2px;bottom:1px;font-size:6px;color:rgba(255,255,255,.45);}
.utility-row{position:absolute;right:82px;bottom:97px;display:flex;flex-direction:column;gap:7px;pointer-events:none;}
.hud.joy-right .utility-row{right:auto;left:82px;}
.utility-btn{position:relative;width:37px;height:37px;border:1px solid rgba(217,183,106,.3);background:rgba(8,9,14,.76);color:#d8ccb2;backdrop-filter:blur(5px);box-shadow:0 3px 10px rgba(0,0,0,.4);}
.utility-btn svg{width:18px;height:18px;}
.utility-btn .qty{position:absolute;right:-3px;bottom:-3px;min-width:15px;height:15px;padding:0 3px;border-radius:8px;background:#3a1718;border:1px solid rgba(255,140,130,.35);color:#f6cbc7;font-size:7.5px;display:grid;place-items:center;font-weight:700;}
.utility-btn.mount-on{color:#f4df9a;border-color:rgba(244,223,154,.6);box-shadow:0 0 15px rgba(217,183,106,.18);}
.interaction-btn{position:absolute;left:50%;bottom:calc(137px + var(--safe-bottom));transform:translateX(-50%);display:flex;align-items:center;gap:7px;padding:8px 15px;background:linear-gradient(180deg,rgba(34,29,21,.92),rgba(10,10,14,.96));border:1px solid rgba(217,183,106,.45);color:#f4e6c8;font-size:10px;letter-spacing:.06em;box-shadow:0 6px 20px rgba(0,0,0,.55);pointer-events:auto;white-space:nowrap;animation:interactIn .25s var(--ease) both;max-width:72vw;overflow:hidden;text-overflow:ellipsis;}
.interaction-btn svg{width:16px;height:16px;color:var(--gold);flex:none;}
.interaction-btn small{font-size:7px;letter-spacing:.13em;text-transform:uppercase;color:var(--gold-dim);}
.interaction-btn .ia-text{overflow:hidden;text-overflow:ellipsis;}
@keyframes interactIn{from{opacity:0;transform:translate(-50%,6px)}to{opacity:1;transform:translate(-50%,0)}}
.target-chip{position:absolute;left:50%;bottom:calc(178px + var(--safe-bottom));transform:translateX(-50%);width:min(64vw,250px);pointer-events:none;text-align:center;filter:drop-shadow(0 2px 6px #000);}
.target-chip .tc-name{font-family:var(--font-display);font-size:10.5px;letter-spacing:.06em;color:#f2dfb4;}
.target-chip .tc-bar{height:4px;background:rgba(0,0,0,.65);border:1px solid rgba(255,255,255,.14);margin-top:3px;}
.target-chip .tc-bar i{display:block;height:100%;background:linear-gradient(90deg,#8d2e2b,#df6453);}
.status-strip{position:absolute;left:50%;bottom:calc(91px + var(--safe-bottom));transform:translateX(-50%);display:flex;gap:5px;pointer-events:none;}
.status-pill{display:flex;align-items:center;gap:3px;height:18px;padding:0 6px;background:rgba(8,9,13,.75);border:1px solid rgba(255,255,255,.1);font-size:7px;text-transform:uppercase;letter-spacing:.07em;color:#c9bfa9;}
.status-pill svg{width:10px;height:10px;color:var(--gold);}
.autosave-flash{position:absolute;right:12px;bottom:calc(92px + var(--safe-bottom));font-size:7px;letter-spacing:.1em;color:rgba(217,183,106,.55);text-transform:uppercase;opacity:0;transition:opacity .3s;}
.autosave-flash.on{opacity:1;}
.death-veil{position:absolute;inset:0;z-index:70;background:radial-gradient(circle at 50% 42%,rgba(38,5,7,.55),rgba(3,3,6,.94) 68%);display:flex;align-items:center;justify-content:center;flex-direction:column;padding:24px;text-align:center;animation:fadeIn .5s both;pointer-events:auto;}
.death-veil h2{font-size:30px;letter-spacing:.18em;color:#e7c7af;text-shadow:0 0 30px rgba(201,86,79,.35);}
.death-veil p{max-width:260px;color:#a99a8e;font-size:11px;line-height:1.6;margin:12px 0 24px;}
.death-veil .btns{display:flex;flex-direction:column;gap:8px;width:210px;}

/* ---------- menu drawer ---------- */
.drawer-backdrop{position:fixed;inset:0;background:rgba(2,2,5,.62);backdrop-filter:blur(3px);animation:fadeIn .18s both;}
.drawer{position:absolute;right:0;top:0;bottom:0;width:min(90%,356px);background:linear-gradient(165deg,rgba(27,25,31,.99),rgba(8,8,13,.995) 60%);border-left:1px solid rgba(217,183,106,.28);box-shadow:-22px 0 60px rgba(0,0,0,.65);display:flex;flex-direction:column;animation:drawerIn .28s var(--ease) both;}
@keyframes drawerIn{from{transform:translateX(24px);opacity:.6}to{transform:none;opacity:1}}
.drawer-head{padding:calc(17px + var(--safe-top)) 18px 14px;border-bottom:1px solid rgba(217,183,106,.15);display:flex;align-items:center;justify-content:space-between;}
.drawer-head .eyebrow{font-size:8px;}
.drawer-name{font-family:var(--font-display);font-size:16px;color:#f2e7cf;margin-top:3px;letter-spacing:.06em;}
.drawer-sub{font-size:9px;color:var(--muted);margin-top:2px;}
.drawer-scroll{padding:14px 14px 24px;overflow-y:auto;flex:1;}
.menu-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px;}
.menu-tile{position:relative;min-height:72px;padding:12px 11px;display:flex;flex-direction:column;justify-content:flex-end;gap:2px;text-align:left;border:1px solid rgba(255,255,255,.08);background:linear-gradient(145deg,rgba(35,33,42,.75),rgba(12,12,17,.85));transition:border-color .18s,transform .12s;overflow:hidden;}
.menu-tile:active{transform:scale(.98);}
.menu-tile svg{width:21px;height:21px;color:var(--gold);opacity:.9;margin-bottom:6px;}
.menu-tile b{font-family:var(--font-display);font-size:11px;letter-spacing:.05em;font-weight:500;color:#e9ddc5;}
.menu-tile span{font-size:8px;color:var(--faint);letter-spacing:.03em;}
.menu-tile::after{content:"";position:absolute;inset:0;background:radial-gradient(90% 70% at 100% 0,rgba(217,183,106,.07),transparent 60%);pointer-events:none;}
.menu-tile.primary{border-color:rgba(217,183,106,.22);background:linear-gradient(145deg,rgba(72,57,31,.55),rgba(14,13,16,.9));}
.menu-tile.trade-on b::after{content:"";display:inline-block;width:5px;height:5px;border-radius:50%;background:#6fbf8a;margin-left:6px;vertical-align:1px;box-shadow:0 0 7px #6fbf8a;}
.drawer-foot{margin-top:16px;border-top:1px solid rgba(255,255,255,.06);padding-top:12px;display:flex;flex-direction:column;gap:6px;}
.drawer-foot .mini-btn{display:flex;align-items:center;gap:9px;padding:10px 8px;color:#a9a394;font-size:10px;letter-spacing:.03em;text-align:left;}
.drawer-foot .mini-btn svg{width:16px;height:16px;color:#8d816a;}
.drawer-foot .mini-btn.danger{color:#d2918c;}

/* ---------- panels ---------- */
.panel-backdrop{position:fixed;inset:0;background:rgba(2,2,5,.76);backdrop-filter:blur(4px);display:flex;align-items:flex-end;justify-content:center;animation:fadeIn .18s both;z-index:70;}
.panel{width:100%;max-width:520px;height:min(94%,860px);display:flex;flex-direction:column;background:linear-gradient(170deg,rgba(24,23,30,.995),rgba(8,8,13,.998) 65%);border:1px solid rgba(217,183,106,.26);border-bottom:0;box-shadow:0 -20px 70px rgba(0,0,0,.65);animation:panelIn .3s var(--ease) both;position:relative;overflow:hidden;}
@keyframes panelIn{from{transform:translateY(28px);opacity:.55}to{transform:none;opacity:1}}
.panel::before{content:"";position:absolute;left:0;right:0;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(244,227,176,.65),transparent);z-index:2;}
.panel-head{flex:none;padding:calc(14px + var(--safe-top)) 15px 12px;border-bottom:1px solid rgba(217,183,106,.14);display:flex;align-items:center;gap:11px;background:linear-gradient(180deg,rgba(28,26,33,.98),rgba(16,16,22,.92));}
.panel-head .back{width:34px;height:34px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.13);color:#cabfa6;flex:none;}
.panel-head .back svg{width:17px;height:17px;}
.panel-title{flex:1;min-width:0;}
.panel-title h2{font-size:16px;letter-spacing:.1em;color:#f1e6cf;line-height:1.2;}
.panel-title p{font-size:8px;letter-spacing:.14em;text-transform:uppercase;color:var(--gold-dim);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.panel-head .resources{display:flex;gap:5px;flex:none;}
.panel-head .currency{height:22px;font-size:8.5px;padding:0 6px;}
.panel-head .close{width:34px;height:34px;display:grid;place-items:center;color:#a49a87;flex:none;border:1px solid transparent;}
.panel-head .close svg{width:18px;height:18px;}
.panel-body{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:13px 14px calc(22px + var(--safe-bottom));}
.panel-body.with-foot{padding-bottom:12px;}
.panel-foot{flex:none;padding:10px 14px calc(11px + var(--safe-bottom));border-top:1px solid rgba(255,255,255,.06);background:rgba(8,8,13,.92);}
.panel-tabs{display:flex;gap:3px;overflow-x:auto;padding:8px 14px;flex:none;border-bottom:1px solid rgba(255,255,255,.05);scrollbar-width:none;}
.panel-tabs::-webkit-scrollbar{display:none;}
.tab{height:30px;padding:0 12px;font-size:9px;letter-spacing:.08em;text-transform:uppercase;color:#8f887a;border:1px solid transparent;white-space:nowrap;flex:none;}
.tab.on{color:#f3e5c5;border-color:rgba(217,183,106,.3);background:rgba(217,183,106,.09);}
.tab .dot{display:inline-block;width:4px;height:4px;border-radius:50%;background:#d9b76a;margin-left:4px;vertical-align:2px;}
.section-block{margin-bottom:16px;}
.section-head{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:8px;gap:8px;}
.section-head h3{font-family:var(--font-display);font-size:12px;letter-spacing:.08em;color:#e7dbc1;}
.section-head span{font-size:8px;letter-spacing:.11em;text-transform:uppercase;color:var(--faint);}
.hint{font-size:9.5px;line-height:1.5;color:#8f887b;}
.hint.gold{color:#b9a37b;}
.hint.red{color:#c98f89;}
.empty-state{padding:38px 18px;text-align:center;border:1px dashed rgba(217,183,106,.2);background:rgba(217,183,106,.025);}
.empty-state svg{width:32px;height:32px;color:#776b52;margin:0 auto 10px;}
.empty-state h3{font-family:var(--font-display);font-size:13px;color:#c6b99e;letter-spacing:.05em;}
.empty-state p{font-size:9.5px;color:#7c776d;line-height:1.55;margin:5px auto 0;max-width:230px;}
.stat-list{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.055);}
.stat-row{display:flex;justify-content:space-between;align-items:center;padding:7px 9px;background:rgba(12,12,18,.9);font-size:9.5px;color:#9d9687;gap:5px;}
.stat-row b{color:#e7dbbe;font-weight:600;font-size:10.5px;}
.stat-row b.up{color:#8fd8a6;}
.stat-row svg{width:12px;height:12px;color:#7d735f;}
.progress-line{height:5px;background:rgba(0,0,0,.5);border:1px solid rgba(255,255,255,.07);}
.progress-line i{display:block;height:100%;background:linear-gradient(90deg,#8a6c36,#d9b76a);}
.panel-actions{display:flex;gap:7px;flex-wrap:wrap;}
.panel-actions .btn{flex:1;min-width:90px;}
.price{display:inline-flex;align-items:center;gap:4px;font-weight:600;color:#e9d39a;font-size:10px;}
.price svg{width:12px;height:12px;color:#8fd8ee;}
.price.gold{color:#e9d39a;}
.price.gold svg{color:#d9b76a;}
.price.no{color:#c98f89;}

/* ---------- item grid & cards ---------- */
.item-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;}
@media(min-width:390px){.item-grid{grid-template-columns:repeat(6,1fr);}}
.item-cell{position:relative;aspect-ratio:1;border:1px solid rgba(255,255,255,.075);background:linear-gradient(145deg,rgba(30,29,38,.8),rgba(13,13,18,.9));display:grid;place-items:center;overflow:hidden;min-width:0;transition:border-color .15s,transform .1s;}
.item-cell:active{transform:scale(.96);}
.item-cell::before{content:"";position:absolute;inset:2px;border:1px solid rgba(255,255,255,.025);pointer-events:none;}
.item-cell .ii{width:63%;height:63%;color:var(--rc,#aaa);filter:drop-shadow(0 2px 3px #000);}
.item-cell .qty{position:absolute;right:2px;bottom:1px;font-size:7.5px;font-weight:700;color:#f5ecd7;text-shadow:0 1px 2px #000,0 0 4px #000;}
