350: export function advanceQuests(player, type, target, count = 1) {
351:   const done = [];
352:   for (const [qid, entry] of Object.entries(player.quests)) {
353:     if (entry.state !== 'active') continue;
354:     const q = getQuest(qid);
355:     if (!q) continue;
356:     let changed = false;
357:     q.objectives.forEach((o, i) => {
358:       if (o.type !== type || o.target !== target) return;
359:       const before = entry.progress[i] ?? 0;
360:       if (before >= o.count) return;
361:       entry.progress[i] = Math.min(o.count, before + count);
362:       if (entry.progress[i] !== before) changed = true;
363:     });
364:     if (changed && questReady(player, qid)) {
365:       entry.state = 'done';
366:       done.push(q);
367:     }
368:   }
369:   return done;
370: }
