1383:   drawWeather(zone) {
1384:     const ctx = this.ctx;
1385:     const t = this.time;
1386:     const w = this.w, h = this.h;
1387:     const type = zone.weather;
1388:     ctx.save();
1389:     if (type === 'snow') {
1390:       ctx.fillStyle = 'rgba(240,250,255,.65)';
1391:       for (let i = 0; i < 70; i++) {
1392:         const x = ((i * 137 + t * 18 + Math.sin(t + i) * 20) % (w + 40)) - 20;
1393:         const y = ((i * 71 + t * 42) % (h + 40)) - 20;
1394:         ctx.globalAlpha = 0.35 + (i % 4) * 0.12;
1395:         ctx.beginPath(); ctx.arc(x, y, 1 + (i % 3) * 0.7, 0, TAU); ctx.fill();
1396:       }
1397:     } else if (type === 'sand') {
1398:       ctx.strokeStyle = 'rgba(230,200,140,.18)'; ctx.lineWidth = 1;
1399:       for (let i = 0; i < 34; i++) {
1400:         const x = ((i * 173 + t * 220) % (w + 80)) - 40;
1401:         const y = ((i * 97 + t * 10) % h);
1402:         ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + 18 + (i % 4) * 6, y + 2); ctx.stroke();
1403:       }
1404:     } else if (type === 'ash') {
1405:       for (let i = 0; i < 60; i++) {
1406:         const x = ((i * 127 + t * 12 + Math.sin(t * 0.5 + i) * 24) % (w + 30)) - 15;
1407:         const y = ((i * 83 + t * 26) % (h + 30)) - 15;
1408:         ctx.fillStyle = i % 3 === 0 ? 'rgba(255,150,100,.4)' : 'rgba(200,180,170,.3)';
1409:         ctx.beginPath(); ctx.arc(x, y, 1 + (i % 3) * 0.6, 0, TAU); ctx.fill();
1410:       }
1411:     } else if (type === 'fireflies' || type === 'spores' || type === 'stars') {
1412:       const color = type === 'spores' ? '140,224,122' : type === 'stars' ? '216,200,255' : '240,220,150';
1413:       ctx.save(); ctx.globalCompositeOperation = 'lighter';
1414:       for (let i = 0; i < 30; i++) {
1415:         const x = ((i * 151 + Math.sin(t * 0.5 + i * 2) * 40 + t * 6) % (w + 40)) - 20;
1416:         const y = (i * 89 + Math.cos(t * 0.7 + i) * 26) % h;
1417:         const a = 0.2 + Math.abs(Math.sin(t * 1.4 + i)) * 0.5;
1418:         const g = ctx.createRadialGradient(x, y, 0, x, y, 5);
1419:         g.addColorStop(0, `rgba(${color},${a})`); g.addColorStop(1, `rgba(${color},0)`);
1420:         ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, 5, 0, TAU); ctx.fill();
1421:       }
1422:       ctx.restore();
1423:     } else if (type === 'mist') {
1424:       for (let i = 0; i < 5; i++) {
1425:         const y = (i * 160 + t * 8) % (h + 200) - 100;
1426:         const x = Math.sin(t * 0.2 + i) * 60;
1427:         const g = ctx.createLinearGradient(0, y, 0, y + 120);
1428:         g.addColorStop(0, 'rgba(180,200,210,0)'); g.addColorStop(0.5, 'rgba(180,200,210,.05)'); g.addColorStop(1, 'rgba(180,200,210,0)');
1429:         ctx.fillStyle = g; ctx.fillRect(x, y, w, 120);
1430:       }
1431:     } else if (type === 'embers') {
1432:       ctx.save(); ctx.globalCompositeOperation = 'lighter';
1433:       for (let i = 0; i < 32; i++) {
1434:         const x = ((i * 119 + t * 20) % (w + 30)) - 15;
1435:         const y = h - ((i * 97 + t * 50) % (h + 40));
1436:         const a = 0.2 + (i % 4) * 0.12;
1437:         ctx.fillStyle = `rgba(255,150,70,${a})`;
1438:         ctx.beginPath(); ctx.arc(x, y, 1 + (i % 3) * 0.6, 0, TAU); ctx.fill();
1439:       }
1440:       ctx.restore();
1441:     }
1442:     ctx.restore();
1443:   }
