.joy-base::before{left:50%;top:12%;bottom:12%;width:1px;}
.joy-base::after{top:50%;left:12%;right:12%;height:1px;}
.joy-knob{position:absolute;width:50px;height:50px;left:calc(50% - 25px);top:calc(50% - 25px);border-radius:50%;border:1px solid rgba(244,227,176,.5);background:radial-gradient(circle at 38% 30%,rgba(217,183,106,.5),rgba(34,29,21,.95) 60%,rgba(12,12,16,.96));box-shadow:0 4px 14px rgba(0,0,0,.6),inset 0 0 14px rgba(244,227,176,.13);transition:transform .05s linear;display:grid;place-items:center;color:rgba(244,227,176,.6);}
.joy-knob svg{width:16px;height:16px;opacity:.75;}
.attack-cluster{right:14px;width:156px;height:158px;pointer-events:none;}
.hud.joy-right .attack-cluster{right:auto;left:14px;}
.skill-btn,.attack-btn,.utility-btn{position:absolute;pointer-events:auto;border-radius:50%;display:grid;place-items:center;touch-action:none;transition:transform .1s var(--ease);}
.skill-btn:active,.attack-btn:active,.utility-btn:active{transform:scale(.94);}
.attack-btn{right:0;bottom:8px;width:78px;height:78px;border:1px solid rgba(244,227,176,.52);background:radial-gradient(circle at 42% 30%,rgba(100,75,35,.92),rgba(40,28,15,.97) 60%,rgba(13,11,10,.98));box-shadow:0 6px 22px rgba(0,0,0,.55),inset 0 0 22px rgba(244,227,176,.12);color:#f7e9c2;}
.attack-btn svg{width:32px;height:32px;filter:drop-shadow(0 0 5px rgba(244,227,176,.2));}
.attack-btn .keycap{position:absolute;right:3px;bottom:2px;font-size:6.5px;color:rgba(244,227,176,.45);letter-spacing:.08em;}
.skill-btn{width:49px;height:49px;background:radial-gradient(circle at 38% 28%,rgba(42,42,58,.9),rgba(10,10,16,.96));border:1px solid rgba(217,183,106,.26);color:var(--skill-color,#d9b76a);box-shadow:0 3px 14px rgba(0,0,0,.5);overflow:hidden;}
.skill-btn svg{width:23px;height:23px;filter:drop-shadow(0 0 4px currentColor);}
.skill-btn .cd{position:absolute;inset:0;border-radius:50%;background:conic-gradient(rgba(2,3,6,.8) var(--cd,0%),transparent 0);pointer-events:none;}
.skill-btn .cd-num{position:absolute;inset:0;display:grid;place-items:center;font-size:12px;font-weight:700;color:#fff;text-shadow:0 1px 3px #000;pointer-events:none;}
.skill-btn.locked{opacity:.45;color:#888;border-color:rgba(255,255,255,.13);}
.skill-btn.s1{right:58px;bottom:94px;}
.skill-btn.s2{right:111px;bottom:58px;}
.skill-btn.s3{right:106px;bottom:3px;}
.hud.joy-right .skill-btn.s1{right:auto;left:58px;}
.hud.joy-right .skill-btn.s2{right:auto;left:111px;}
.hud.joy-right .skill-btn.s3{right:auto;left:106px;}
.skill-btn .skey{position:absolute;right:2px;bottom:1px;font-size:6px;color:rgba(255,255,255,.45);}
.utility-row{position:absolute;right:82px;bottom:97px;display:flex;flex-direction:column;gap:7px;pointer-events:none;}
.hud.joy-right .utility-row{right:auto;left:82px;}
.utility-btn{position:relative;width:37px;height:37px;border:1px solid rgba(217,183,106,.3);background:rgba(8,9,14,.76);color:#d8ccb2;backdrop-filter:blur(5px);box-shadow:0 3px 10px rgba(0,0,0,.4);}
.utility-btn svg{width:18px;height:18px;}
.utility-btn .qty{position:absolute;right:-3px;bottom:-3px;min-width:15px;height:15px;padding:0 3px;border-radius:8px;background:#3a1718;border:1px solid rgba(255,140,130,.35);color:#f6cbc7;font-size:7.5px;display:grid;place-items:center;font-weight:700;}
.utility-btn.mount-on{color:#f4df9a;border-color:rgba(244,223,154,.6);box-shadow:0 0 15px rgba(217,183,106,.18);}
.interaction-btn{position:absolute;left:50%;bottom:calc(137px + var(--safe-bottom));transform:translateX(-50%);display:flex;align-items:center;gap:7px;padding:8px 15px;background:linear-gradient(180deg,rgba(34,29,21,.92),rgba(10,10,14,.96));border:1px solid rgba(217,183,106,.45);color:#f4e6c8;font-size:10px;letter-spacing:.06em;box-shadow:0 6px 20px rgba(0,0,0,.55);pointer-events:auto;white-space:nowrap;animation:interactIn .25s var(--ease) both;max-width:72vw;overflow:hidden;text-overflow:ellipsis;}
.interaction-btn svg{width:16px;height:16px;color:var(--gold);flex:none;}
.interaction-btn small{font-size:7px;letter-spacing:.13em;text-transform:uppercase;color:var(--gold-dim);}
.interaction-btn .ia-text{overflow:hidden;text-overflow:ellipsis;}
@keyframes interactIn{from{opacity:0;transform:translate(-50%,6px)}to{opacity:1;transform:translate(-50%,0)}}
.target-chip{position:absolute;left:50%;bottom:calc(178px + var(--safe-bottom));transform:translateX(-50%);width:min(64vw,250px);pointer-events:none;text-align:center;filter:drop-shadow(0 2px 6px #000);}
.target-chip .tc-name{font-family:var(--font-display);font-size:10.5px;letter-spacing:.06em;color:#f2dfb4;}
.target-chip .tc-bar{height:4px;background:rgba(0,0,0,.65);border:1px solid rgba(255,255,255,.14);margin-top:3px;}
.target-chip .tc-bar i{display:block;height:100%;background:linear-gradient(90deg,#8d2e2b,#df6453);}
.status-strip{position:absolute;left:50%;bottom:calc(91px + var(--safe-bottom));transform:translateX(-50%);display:flex;gap:5px;pointer-events:none;}
.status-pill{display:flex;align-items:center;gap:3px;height:18px;padding:0 6px;background:rgba(8,9,13,.75);border:1px solid rgba(255,255,255,.1);font-size:7px;text-transform:uppercase;letter-spacing:.07em;color:#c9bfa9;}
.status-pill svg{width:10px;height:10px;color:var(--gold);}
.autosave-flash{position:absolute;right:12px;bottom:calc(92px + var(--safe-bottom));font-size:7px;letter-spacing:.1em;color:rgba(217,183,106,.55);text-transform:uppercase;opacity:0;transition:opacity .3s;}
.autosave-flash.on{opacity:1;}
.death-veil{position:absolute;inset:0;z-index:70;background:radial-gradient(circle at 50% 42%,rgba(38,5,7,.55),rgba(3,3,6,.94) 68%);display:flex;align-items:center;justify-content:center;flex-direction:column;padding:24px;text-align:center;animation:fadeIn .5s both;pointer-events:auto;}
.death-veil h2{font-size:30px;letter-spacing:.18em;color:#e7c7af;text-shadow:0 0 30px rgba(201,86,79,.35);}
.death-veil p{max-width:260px;color:#a99a8e;font-size:11px;line-height:1.6;margin:12px 0 24px;}
.death-veil .btns{display:flex;flex-direction:column;gap:8px;width:210px;}

/* ---------- menu drawer ---------- */
.drawer-backdrop{position:fixed;inset:0;background:rgba(2,2,5,.62);backdrop-filter:blur(3px);animation:fadeIn .18s both;}
.drawer{position:absolute;right:0;top:0;bottom:0;width:min(90%,356px);background:linear-gradient(165deg,rgba(27,25,31,.99),rgba(8,8,13,.995) 60%);border-left:1px solid rgba(217,183,106,.28);box-shadow:-22px 0 60px rgba(0,0,0,.65);display:flex;flex-direction:column;animation:drawerIn .28s var(--ease) both;}
@keyframes drawerIn{from{transform:translateX(24px);opacity:.6}to{transform:none;opacity:1}}
.drawer-head{padding:calc(17px + var(--safe-top)) 18px 14px;border-bottom:1px solid rgba(217,183,106,.15);display:flex;align-items:center;justify-content:space-between;}
.drawer-head .eyebrow{font-size:8px;}
.drawer-name{font-family:var(--font-display);font-size:16px;color:#f2e7cf;margin-top:3px;letter-spacing:.06em;}
.drawer-sub{font-size:9px;color:var(--muted);margin-top:2px;}
.drawer-scroll{padding:14px 14px 24px;overflow-y:auto;flex:1;}
.menu-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px;}
.menu-tile{position:relative;min-height:72px;padding:12px 11px;display:flex;flex-direction:column;justify-content:flex-end;gap:2px;text-align:left;border:1px solid rgba(255,255,255,.08);background:linear-gradient(145deg,rgba(35,33,42,.75),rgba(12,12,17,.85));transition:border-color .18s,transform .12s;overflow:hidden;}
.menu-tile:active{transform:scale(.98);}
.menu-tile svg{width:21px;height:21px;color:var(--gold);opacity:.9;margin-bottom:6px;}
.menu-tile b{font-family:var(--font-display);font-size:11px;letter-spacing:.05em;font-weight:500;color:#e9ddc5;}
.menu-tile span{font-size:8px;color:var(--faint);letter-spacing:.03em;}
.menu-tile::after{content:"";position:absolute;inset:0;background:radial-gradient(90% 70% at 100% 0,rgba(217,183,106,.07),transparent 60%);pointer-events:none;}
.menu-tile.primary{border-color:rgba(217,183,106,.22);background:linear-gradient(145deg,rgba(72,57,31,.55),rgba(14,13,16,.9));}
.menu-tile.trade-on b::after{content:"";display:inline-block;width:5px;height:5px;border-radius:50%;background:#6fbf8a;margin-left:6px;vertical-align:1px;box-shadow:0 0 7px #6fbf8a;}
.drawer-foot{margin-top:16px;border-top:1px solid rgba(255,255,255,.06);padding-top:12px;display:flex;flex-direction:column;gap:6px;}
.drawer-foot .mini-btn{display:flex;align-items:center;gap:9px;padding:10px 8px;color:#a9a394;font-size:10px;letter-spacing:.03em;text-align:left;}
.drawer-foot .mini-btn svg{width:16px;height:16px;color:#8d816a;}
.drawer-foot .mini-btn.danger{color:#d2918c;}

/* ---------- panels ---------- */
.panel-backdrop{position:fixed;inset:0;background:rgba(2,2,5,.76);backdrop-filter:blur(4px);display:flex;align-items:flex-end;justify-content:center;animation:fadeIn .18s both;z-index:70;}
.panel{width:100%;max-width:520px;height:min(94%,860px);display:flex;flex-direction:column;background:linear-gradient(170deg,rgba(24,23,30,.995),rgba(8,8,13,.998) 65%);border:1px solid rgba(217,183,106,.26);border-bottom:0;box-shadow:0 -20px 70px rgba(0,0,0,.65);animation:panelIn .3s var(--ease) both;position:relative;overflow:hidden;}
@keyframes panelIn{from{transform:translateY(28px);opacity:.55}to{transform:none;opacity:1}}
.panel::before{content:"";position:absolute;left:0;right:0;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(244,227,176,.65),transparent);z-index:2;}
.panel-head{flex:none;padding:calc(14px + var(--safe-top)) 15px 12px;border-bottom:1px solid rgba(217,183,106,.14);display:flex;align-items:center;gap:11px;background:linear-gradient(180deg,rgba(28,26,33,.98),rgba(16,16,22,.92));}
.panel-head .back{width:34px;height:34px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.13);color:#cabfa6;flex:none;}
.panel-head .back svg{width:17px;height:17px;}
.panel-title{flex:1;min-width:0;}
.panel-title h2{font-size:16px;letter-spacing:.1em;color:#f1e6cf;line-height:1.2;}
.panel-title p{font-size:8px;letter-spacing:.14em;text-transform:uppercase;color:var(--gold-dim);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.panel-head .resources{display:flex;gap:5px;flex:none;}
.panel-head .currency{height:22px;font-size:8.5px;padding:0 6px;}
.panel-head .close{width:34px;height:34px;display:grid;place-items:center;color:#a49a87;flex:none;border:1px solid transparent;}
.panel-head .close svg{width:18px;height:18px;}
.panel-body{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:13px 14px calc(22px + var(--safe-bottom));}
.panel-body.with-foot{padding-bottom:12px;}
.panel-foot{flex:none;padding:10px 14px calc(11px + var(--safe-bottom));border-top:1px solid rgba(255,255,255,.06);background:rgba(8,8,13,.92);}
.panel-tabs{display:flex;gap:3px;overflow-x:auto;padding:8px 14px;flex:none;border-bottom:1px solid rgba(255,255,255,.05);scrollbar-width:none;}
.panel-tabs::-webkit-scrollbar{display:none;}
.tab{height:30px;padding:0 12px;font-size:9px;letter-spacing:.08em;text-transform:uppercase;color:#8f887a;border:1px solid transparent;white-space:nowrap;flex:none;}
.tab.on{color:#f3e5c5;border-color:rgba(217,183,106,.3);background:rgba(217,183,106,.09);}
.tab .dot{display:inline-block;width:4px;height:4px;border-radius:50%;background:#d9b76a;margin-left:4px;vertical-align:2px;}
.section-block{margin-bottom:16px;}
.section-head{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:8px;gap:8px;}
.section-head h3{font-family:var(--font-display);font-size:12px;letter-spacing:.08em;color:#e7dbc1;}
.section-head span{font-size:8px;letter-spacing:.11em;text-transform:uppercase;color:var(--faint);}
.hint{font-size:9.5px;line-height:1.5;color:#8f887b;}
.hint.gold{color:#b9a37b;}
.hint.red{color:#c98f89;}
.empty-state{padding:38px 18px;text-align:center;border:1px dashed rgba(217,183,106,.2);background:rgba(217,183,106,.025);}
.empty-state svg{width:32px;height:32px;color:#776b52;margin:0 auto 10px;}
.empty-state h3{font-family:var(--font-display);font-size:13px;color:#c6b99e;letter-spacing:.05em;}
.empty-state p{font-size:9.5px;color:#7c776d;line-height:1.55;margin:5px auto 0;max-width:230px;}
.stat-list{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.055);}
.stat-row{display:flex;justify-content:space-between;align-items:center;padding:7px 9px;background:rgba(12,12,18,.9);font-size:9.5px;color:#9d9687;gap:5px;}
.stat-row b{color:#e7dbbe;font-weight:600;font-size:10.5px;}
.stat-row b.up{color:#8fd8a6;}
.stat-row svg{width:12px;height:12px;color:#7d735f;}
.progress-line{height:5px;background:rgba(0,0,0,.5);border:1px solid rgba(255,255,255,.07);}
.progress-line i{display:block;height:100%;background:linear-gradient(90deg,#8a6c36,#d9b76a);}
.panel-actions{display:flex;gap:7px;flex-wrap:wrap;}
.panel-actions .btn{flex:1;min-width:90px;}
.price{display:inline-flex;align-items:center;gap:4px;font-weight:600;color:#e9d39a;font-size:10px;}
.price svg{width:12px;height:12px;color:#8fd8ee;}
.price.gold{color:#e9d39a;}
.price.gold svg{color:#d9b76a;}
.price.no{color:#c98f89;}

/* ---------- item grid & cards ---------- */
.item-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;}
@media(min-width:390px){.item-grid{grid-template-columns:repeat(6,1fr);}}
.item-cell{position:relative;aspect-ratio:1;border:1px solid rgba(255,255,255,.075);background:linear-gradient(145deg,rgba(30,29,38,.8),rgba(13,13,18,.9));display:grid;place-items:center;overflow:hidden;min-width:0;transition:border-color .15s,transform .1s;}
.item-cell:active{transform:scale(.96);}
.item-cell::before{content:"";position:absolute;inset:2px;border:1px solid rgba(255,255,255,.025);pointer-events:none;}
.item-cell .ii{width:63%;height:63%;color:var(--rc,#aaa);filter:drop-shadow(0 2px 3px #000);}
.item-cell .qty{position:absolute;right:2px;bottom:1px;font-size:7.5px;font-weight:700;color:#f5ecd7;text-shadow:0 1px 2px #000,0 0 4px #000;}
.item-cell .tier{position:absolute;left:2px;top:1px;font-size:5.8px;font-weight:700;letter-spacing:.04em;color:var(--rc);opacity:.9;text-shadow:0 1px 2px #000;}
.item-cell .ilvl{position:absolute;left:2px;bottom:1px;font-size:6px;color:rgba(255,255,255,.5);text-shadow:0 1px 2px #000;}
.item-cell.empty{opacity:.6;background:rgba(8,8,12,.45);border-style:dashed;border-color:rgba(255,255,255,.07);}
.item-cell.empty .ii{color:rgba(255,255,255,.14);}
.item-cell.selected{border-color:rgba(244,227,176,.7);box-shadow:inset 0 0 12px rgba(217,183,106,.14);}
.item-cell.r-grey{--rc:#a7a7a7}
.item-cell.r-common{--rc:#dcd6c5}
.item-cell.r-green{--rc:#78d69b}
.item-cell.r-blue{--rc:#6fb5f2}
.item-cell.r-purple{--rc:#b98af0}
.item-cell.r-legendary{--rc:#f4b95e}
.item-cell.r-mythic{--rc:#ff7a6b}
.item-cell.r-divine{--rc:#f6f0c8}
.item-cell.r-legendary::after,.item-cell.r-mythic::after,.item-cell.r-divine::after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 50% 120%,rgba(244,185,94,.16),transparent 65%);pointer-events:none;}
.item-card{padding:11px;border:1px solid rgba(217,183,106,.18);background:linear-gradient(160deg,rgba(32,30,38,.7),rgba(10,10,15,.85));position:relative;}
.item-card::before{content:"";position:absolute;left:0;top:0;bottom:0;width:2px;background:var(--rc,#d9b76a);opacity:.85;}
.item-card-head{display:flex;gap:10px;align-items:center;}
.item-icon-lg{width:48px;height:48px;display:grid;place-items:center;border:1px solid color-mix(in srgb,var(--rc,#d9b76a) 40%,transparent);background:radial-gradient(circle at 40% 30%,rgba(255,255,255,.06),rgba(0,0,0,.3));color:var(--rc);flex:none;}
.item-icon-lg svg{width:28px;height:28px;}
.item-card-head .ic-name{font-family:var(--font-display);font-size:13px;line-height:1.2;color:var(--rc,#efe4c9);}
.item-card-head .ic-meta{font-size:8px;letter-spacing:.08em;text-transform:uppercase;color:#8e8778;margin-top:3px;display:flex;gap:8px;flex-wrap:wrap;}
.item-stats{display:grid;grid-template-columns:1fr 1fr;gap:4px 12px;margin-top:11px;padding-top:9px;border-top:1px solid rgba(255,255,255,.07);}
.item-stat{display:flex;justify-content:space-between;font-size:9px;color:#a8a08f;gap:5px;}
.item-stat b{color:#e8dcc1;font-weight:600;}
.item-desc{font-size:9.5px;line-height:1.55;color:#918a7d;margin-top:9px;}
.item-actions{display:flex;gap:6px;margin-top:11px;}
.item-actions .btn{flex:1;}

/* ---------- panel-specific ---------- */
.eq-layout{display:grid;grid-template-columns:72px 1fr;gap:8px;align-items:start;}
.eq-slots{display:grid;grid-template-columns:1fr;gap:4px;}
.eq-slot{position:relative;height:47px;border:1px solid rgba(255,255,255,.07);background:linear-gradient(145deg,rgba(28,27,35,.75),rgba(11,11,16,.9));display:flex;align-items:center;gap:5px;padding:3px 5px;overflow:hidden;}
.eq-slot .ii{width:28px;height:28px;color:var(--rc,#8f8878);flex:none;}
.eq-slot .en{font-size:6.5px;line-height:1.15;color:#a29a8a;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;}
.eq-slot.empty .ii{color:rgba(255,255,255,.16);}
.eq-slot .ilvl{position:absolute;right:2px;top:1px;font-size:5.5px;color:#6f6a5e;}

.char-hero-wrap{position:relative;height:296px;border:1px solid rgba(217,183,106,.18);background:radial-gradient(80% 75% at 50% 35%,rgba(38,32,50,.8),rgba(9,9,14,.95));overflow:hidden;margin-bottom:11px;}
.char-hero-wrap::after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 55%,rgba(5,5,9,.7));pointer-events:none;}
#charHeroCanvas{width:100%;height:100%;display:block;}
.char-hero-meta{position:absolute;left:12px;right:12px;bottom:10px;z-index:2;display:flex;justify-content:space-between;align-items:flex-end;gap:10px;}
.char-hero-meta h3{font-size:16px;color:#f3e7cd;letter-spacing:.05em;}
.char-hero-meta .ch-sub{font-size:8.5px;color:#b7a98d;letter-spacing:.08em;text-transform:uppercase;margin-top:2px;}
.ch-power{text-align:right;}
.ch-power b{display:block;font-family:var(--font-display);font-size:20px;color:#f4df9a;line-height:1;}
.ch-power span{font-size:7px;letter-spacing:.14em;color:var(--faint);text-transform:uppercase;}
.char-tags{display:flex;gap:4px;flex-wrap:wrap;margin-bottom:10px;}
.char-tags .chip{font-size:8px;padding:3px 6px;}
.stone-card{padding:10px;border:1px solid rgba(244,223,154,.22);background:linear-gradient(145deg,rgba(61,49,27,.25),rgba(13,13,18,.8));}
.stone-card .sc-title{font-family:var(--font-display);font-size:11px;color:#f0dda6;display:flex;align-items:center;gap:6px;}
.stone-card .sc-title svg{width:14px;height:14px;}
.stone-bonus{display:flex;justify-content:space-between;font-size:9px;color:#a99b7f;padding:3px 0;border-bottom:1px solid rgba(255,255,255,.04);}
.stone-bonus b{color:#dccfae;}

.inv-section-title{display:flex;align-items:center;justify-content:space-between;margin:0 0 6px;font-size:8px;letter-spacing:.15em;text-transform:uppercase;color:var(--gold-dim);}
.inv-section-title span{color:#6f6a5e;letter-spacing:.02em;text-transform:none;font-size:8.5px;}
.inv-grid-wrap{margin-bottom:15px;}
.inventory-equip-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-bottom:15px;}
.inventory-equip-grid .eq-slot{height:52px;}
.fusion-group{padding:10px;border:1px solid rgba(255,255,255,.08);background:rgba(15,15,21,.7);margin-bottom:8px;}
.fusion-items{display:flex;gap:6px;align-items:center;margin-top:7px;}
.fusion-items .slot-mini{width:36px;height:36px;border:1px solid rgba(255,255,255,.08);display:grid;place-items:center;color:var(--rc,#a99);background:rgba(0,0,0,.25);}
.fusion-items .slot-mini svg{width:21px;height:21px;}
.fusion-items .plus{font-size:10px;color:#6d6658;}
.fusion-group .fg-head{display:flex;justify-content:space-between;gap:8px;align-items:center;}
