.fusion-result{display:flex;align-items:center;gap:8px;padding:9px;border:1px solid rgba(244,223,154,.2);background:rgba(217,183,106,.05);margin-top:9px;}

.fusion-result{display:flex;align-items:center;gap:8px;padding:9px;border:1px solid rgba(244,223,154,.2);background:rgba(217,183,106,.05);margin-top:9px;}
