.quest-card .btn{min-height:28px;font-size:8px;padding:0 10px;}
.quest-tag{font-size:6.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--gold);border:1px solid rgba(217,183,106,.22);padding:2px 5px;white-space:nowrap;}
.quest-tag.done{color:#8fe5a4;border-color:rgba(111,191,138,.3);}

.skill-card{padding:11px;border:1px solid rgba(255,255,255,.07);background:linear-gradient(145deg,rgba(28,27,36,.68),rgba(10,10,15,.84));margin-bottom:8px;display:flex;gap:11px;align-items:flex-start;}
.skill-icon{width:48px;height:48px;flex:none;display:grid;place-items:center;border:1px solid rgba(217,183,106,.24);background:radial-gradient(circle at 40% 30%,rgba(255,255,255,.07),rgba(0,0,0,.25));color:var(--sc,#d9b76a);}
.skill-icon svg{width:26px;height:26px;filter:drop-shadow(0 0 5px currentColor);}
.skill-card h3{font-family:var(--font-display);font-size:12px;color:#ebdec4;}
.skill-card .sk-meta{display:flex;gap:8px;flex-wrap:wrap;font-size:7.5px;letter-spacing:.06em;text-transform:uppercase;color:#827b6d;margin-top:3px;}
.skill-card .sk-desc{font-size:9px;line-height:1.5;color:#928b7d;margin-top:5px;}
.skill-card.locked{opacity:.55;}
.skill-rank{margin-left:auto;text-align:right;flex:none;}
.skill-rank b{display:block;font-family:var(--font-display);font-size:14px;color:#d9c596;}
.skill-rank span{font-size:6.5px;letter-spacing:.1em;color:#7b7468;text-transform:uppercase;}
.passive-card{padding:10px;border:1px solid rgba(111,191,138,.2);background:rgba(111,191,138,.035);display:flex;gap:10px;align-items:center;}
.passive-card svg{width:24px;height:24px;color:#89c99f;}

.world-map{position:relative;height:214px;border:1px solid rgba(217,183,106,.2);background:radial-gradient(60% 70% at 50% 50%,rgba(39,36,55,.7),rgba(8,8,13,.96));overflow:hidden;margin-bottom:12px;}
.world-map::before{content:"";position:absolute;inset:0;background-image:radial-gradient(circle,rgba(255,255,255,.35) .5px,transparent .6px);background-size:37px 29px;opacity:.15;}
.map-zone{position:absolute;transform:translate(-50%,-50%);display:flex;flex-direction:column;align-items:center;gap:4px;z-index:2;}
.map-node{width:24px;height:24px;border-radius:50%;border:1px solid rgba(217,183,106,.55);background:rgba(10,10,16,.9);display:grid;place-items:center;color:#ead9ab;font-size:7px;font-family:var(--font-display);box-shadow:0 0 0 3px rgba(217,183,106,.04);}
.map-node.current{background:rgba(217,183,106,.24);box-shadow:0 0 14px rgba(217,183,106,.3);}
.map-node.locked{border-color:rgba(255,255,255,.16);color:#67625a;}
.map-zone span{font-size:6.5px;text-transform:uppercase;letter-spacing:.08em;color:#9e947f;white-space:nowrap;text-shadow:0 1px 3px #000;}
.map-path{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;opacity:.35;}
.zone-card{padding:10px;border:1px solid rgba(255,255,255,.07);background:linear-gradient(145deg,rgba(28,27,35,.65),rgba(10,10,15,.83));margin-bottom:7px;display:grid;grid-template-columns:44px 1fr auto;gap:9px;align-items:center;}
.zone-card.current{border-color:rgba(217,183,106,.3);}
.zone-card.locked{opacity:.6;}
.zone-number{width:44px;height:44px;border:1px solid rgba(217,183,106,.2);display:grid;place-items:center;font-family:var(--font-display);font-size:17px;color:#ccb886;background:rgba(0,0,0,.2);}
.zone-card h3{font-family:var(--font-display);font-size:11.5px;color:#e8dcc2;letter-spacing:.04em;}
.zone-card .zc-meta{font-size:8px;color:#8b8374;margin-top:2px;}
.zone-card .zc-tags{display:flex;gap:3px;margin-top:4px;flex-wrap:wrap;}
.zone-card .zc-tags span{font-size:6.5px;border:1px solid rgba(255,255,255,.08);padding:1px 4px;color:#8f887a;text-transform:uppercase;letter-spacing:.06em;}
.zone-card .btn{min-height:30px;font-size:8px;padding:0 9px;}

.store-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px;}
.store-card{border:1px solid rgba(255,255,255,.075);background:linear-gradient(155deg,rgba(32,30,39,.7),rgba(9,9,14,.9));padding:9px;display:flex;flex-direction:column;position:relative;overflow:hidden;min-height:156px;}
.store-card::before{content:"";position:absolute;top:-30px;right:-30px;width:90px;height:90px;border-radius:50%;background:radial-gradient(circle,var(--sc,rgba(217,183,106,.15)),transparent 70%);pointer-events:none;}
.store-visual{height:66px;display:grid;place-items:center;margin-bottom:5px;color:var(--sc,var(--gold));position:relative;}
.store-visual svg{width:42px;height:42px;filter:drop-shadow(0 4px 8px rgba(0,0,0,.5));}
.store-card h3{font-family:var(--font-display);font-size:10.5px;color:#e7d9bd;line-height:1.2;}
.store-card p{font-size:8px;line-height:1.4;color:#817a6d;margin:3px 0 8px;flex:1;}
.store-card .store-buy{display:flex;align-items:center;justify-content:space-between;gap:5px;}
.store-card .store-buy .btn{min-height:27px;font-size:7.5px;padding:0 8px;}
.store-card.owned{border-color:rgba(111,191,138,.28);}
.owned-badge{position:absolute;right:6px;top:6px;font-size:6px;letter-spacing:.09em;text-transform:uppercase;color:#8fe5a4;border:1px solid rgba(111,191,138,.28);padding:1px 4px;}
.shop-tabs{grid-template-columns:repeat(4,1fr);display:grid;}
.daily-card{padding:14px;border:1px solid rgba(111,191,138,.25);background:linear-gradient(145deg,rgba(33,52,39,.25),rgba(10,14,13,.8));margin-bottom:10px;display:flex;align-items:center;gap:12px;}
.daily-card svg{width:32px;height:32px;color:#a7dbaf;}
.daily-card h3{font-family:var(--font-display);font-size:12px;color:#d8e9d4;}
.daily-card p{font-size:8.5px;color:#849686;margin-top:2px;}
.daily-card .btn{margin-left:auto;flex:none;}

.forge-hero{padding:14px;border:1px solid rgba(255,138,92,.2);background:radial-gradient(90% 120% at 50% 0,rgba(92,45,25,.24),rgba(11,10,13,.85));margin-bottom:12px;text-align:center;}
.forge-hero svg{width:34px;height:34px;color:#ffac70;margin:0 auto 5px;}
.forge-hero h3{font-family:var(--font-display);font-size:13px;color:#eed8b6;}
.forge-hero p{font-size:9px;color:#988773;line-height:1.5;margin-top:4px;}
.forge-recipe{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:9px;border:1px solid rgba(255,255,255,.07);background:rgba(14,14,20,.6);margin-bottom:6px;}
.forge-recipe .fr-name{font-size:10px;color:#d5c7ab;}
.forge-recipe .fr-cost{font-size:8px;color:#8b8273;display:flex;gap:8px;flex-wrap:wrap;margin-top:2px;}
.forge-recipe .btn{min-height:28px;font-size:7.5px;padding:0 9px;flex:none;}
.slot-picker{display:grid;grid-template-columns:repeat(5,1fr);gap:4px;margin:7px 0 10px;}
.slot-picker button{height:36px;border:1px solid rgba(255,255,255,.08);display:grid;place-items:center;color:#938a78;background:rgba(0,0,0,.2);}
.slot-picker button.on{border-color:rgba(217,183,106,.45);color:#f0dfb6;background:rgba(217,183,106,.08);}
.slot-picker svg{width:18px;height:18px;}

.storage-columns{display:grid;grid-template-columns:1fr 1fr;gap:9px;}
.storage-panel{border:1px solid rgba(255,255,255,.07);background:rgba(10,10,15,.5);padding:7px;min-height:120px;}
.storage-panel h3{font-family:var(--font-display);font-size:9px;color:#c9bda3;letter-spacing:.07em;margin-bottom:6px;display:flex;justify-content:space-between;}
.storage-panel h3 span{font-size:7px;color:#6f6a5e;}
.storage-panel .item-grid{grid-template-columns:repeat(4,1fr);}
.storage-panel .item-cell .ii{width:58%;height:58%;}

.mount-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;}
.mount-card{border:1px solid rgba(255,255,255,.07);background:linear-gradient(150deg,rgba(30,28,37,.7),rgba(9,9,14,.88));padding:10px;text-align:center;position:relative;}
.mount-card.owned{border-color:rgba(217,183,106,.25);}
.mount-card.active{border-color:rgba(244,223,154,.55);box-shadow:inset 0 0 20px rgba(217,183,106,.055);}
.mount-art{height:56px;display:grid;place-items:center;color:var(--mc,#d9b76a);}
.mount-art svg{width:44px;height:44px;filter:drop-shadow(0 4px 8px #000);}
.mount-card h3{font-family:var(--font-display);font-size:10px;color:#e4d6b9;}
.mount-card p{font-size:7.5px;line-height:1.4;color:#7f786b;margin:3px 0 7px;min-height:30px;}
.mount-card .btn{min-height:27px;font-size:7px;padding:0 8px;width:100%;}
.wardrobe-section{margin-bottom:14px;}
.wig-row{display:flex;gap:5px;overflow-x:auto;padding-bottom:3px;scrollbar-width:none;}
.wig-row::-webkit-scrollbar{display:none;}
.wig{width:42px;height:42px;flex:none;border:1px solid rgba(255,255,255,.09);display:grid;place-items:center;color:#a49a86;background:rgba(255,255,255,.025);}
.wig.on{border-color:rgba(217,183,106,.55);color:#f3e4c4;background:rgba(217,183,106,.09);}
.swatch-row{display:flex;gap:6px;flex-wrap:wrap;}
.swatch{width:27px;height:27px;border-radius:50%;border:2px solid rgba(255,255,255,.12);position:relative;}
.swatch.on{border-color:#f4e3b0;box-shadow:0 0 0 2px rgba(244,227,176,.18);}
.cosmetic-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px;}
.cosmetic-chip{padding:8px;border:1px solid rgba(255,255,255,.08);background:rgba(15,15,21,.6);display:flex;align-items:center;gap:7px;}
.cosmetic-chip svg{width:20px;height:20px;color:var(--cc,#d9b76a);flex:none;}
.cosmetic-chip .cc-name{font-size:9px;color:#cfc3a9;line-height:1.2;}
.cosmetic-chip .cc-sub{font-size:7px;color:#6e685c;}
.cosmetic-chip.on{border-color:rgba(217,183,106,.4);}

.trade-offline{border:1px solid rgba(217,183,106,.18);background:radial-gradient(100% 90% at 50% 0,rgba(49,41,68,.28),rgba(9,9,14,.9));padding:18px 15px;text-align:center;margin-bottom:12px;}
.trade-offline svg{width:34px;height:34px;color:#9a83c5;margin:0 auto 8px;}
.trade-offline h3{font-family:var(--font-display);font-size:13px;color:#dcd0ed;}
.trade-offline p{font-size:9.5px;line-height:1.55;color:#8f8796;margin:6px auto 12px;max-width:270px;}
.server-row{display:flex;gap:6px;margin-top:8px;}
.server-row input{flex:1;min-width:0;height:36px;padding:0 10px;background:rgba(0,0,0,.35);border:1px solid rgba(255,255,255,.12);font-size:9.5px;color:#cfc8bb;}
.server-row .btn{min-height:36px;font-size:8px;padding:0 12px;}
.connection-status{display:flex;align-items:center;justify-content:center;gap:5px;font-size:8px;letter-spacing:.1em;text-transform:uppercase;color:#8b8375;margin-top:9px;}
.connection-status .dot{width:5px;height:5px;border-radius:50%;background:#6d6658;}
.connection-status.online{color:#8fe5a4;}
.connection-status.online .dot{background:#6fbf8a;box-shadow:0 0 7px #6fbf8a;}
.connection-status.error{color:#d59c96;}
.connection-status.error .dot{background:#c9564f;}
.online-list{margin-top:10px;}
.online-player{display:flex;align-items:center;gap:8px;padding:7px 8px;border-bottom:1px solid rgba(255,255,255,.05);font-size:9px;color:#b9ad97;}
.online-player .op-dot{width:5px;height:5px;border-radius:50%;background:#6fbf8a;}
.online-player b{color:#e1d3b7;font-weight:600;}
.online-player span{margin-left:auto;font-size:7.5px;color:#7e776b;text-transform:uppercase;letter-spacing:.06em;}
.trade-steps{display:flex;flex-direction:column;gap:6px;margin-top:10px;text-align:left;}
.trade-step{display:flex;gap:8px;font-size:9px;line-height:1.45;color:#918a7e;}
.trade-step b{width:16px;height:16px;border-radius:50%;border:1px solid rgba(217,183,106,.3);display:grid;place-items:center;font-size:7px;color:#d9b76a;flex:none;}

.settings-group{border:1px solid rgba(255,255,255,.065);background:rgba(13,13,19,.55);margin-bottom:10px;}
.settings-group h3{font-family:var(--font-display);font-size:9px;letter-spacing:.13em;text-transform:uppercase;color:var(--gold);padding:9px 11px;border-bottom:1px solid rgba(255,255,255,.05);}
.setting-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 11px;border-bottom:1px solid rgba(255,255,255,.04);min-height:44px;}
.setting-row:last-child{border-bottom:0;}
.setting-row .sr-label{font-size:10px;color:#cfc5b2;line-height:1.25;}
.setting-row .sr-hint{font-size:7.5px;color:#766f64;line-height:1.35;margin-top:2px;max-width:210px;}
.setting-row .sr-control{flex:none;display:flex;gap:4px;align-items:center;}
.seg{display:flex;border:1px solid rgba(255,255,255,.1);background:rgba(0,0,0,.25);}
.seg button{height:26px;padding:0 8px;font-size:8px;letter-spacing:.05em;color:#888175;}
.seg button.on{background:rgba(217,183,106,.16);color:#f3e5c6;}
.toggle{width:38px;height:21px;border-radius:11px;border:1px solid rgba(255,255,255,.15);background:rgba(0,0,0,.4);position:relative;transition:background .18s,border-color .18s;}
.toggle::after{content:"";position:absolute;left:2px;top:2px;width:15px;height:15px;border-radius:50%;background:#6f6a5e;transition:transform .18s,background .18s;}
.toggle.on{background:rgba(111,191,138,.15);border-color:rgba(111,191,138,.4);}
.toggle.on::after{transform:translateX(17px);background:#8fd8a6;}
.save-info{font-size:8.5px;line-height:1.7;color:#8d8578;}
.save-info b{color:#c8ba9f;font-weight:500;}
.settings-danger{border-color:rgba(201,86,79,.25);}
.settings-danger h3{color:#d98f88;}

/* dialogue */
.dialogue{position:fixed;left:0;right:0;bottom:0;z-index:75;padding:0 10px calc(10px + var(--safe-bottom));animation:dialogueIn .32s var(--ease) both;pointer-events:none;}
.dialogue-inner{max-width:500px;margin:0 auto;background:linear-gradient(165deg,rgba(28,25,30,.99),rgba(8,8,13,.995));border:1px solid rgba(217,183,106,.32);box-shadow:0 -15px 55px rgba(0,0,0,.7);position:relative;pointer-events:auto;}
.dialogue-inner::before{content:"";position:absolute;inset:4px;border:1px solid rgba(217,183,106,.075);pointer-events:none;}
.dialogue-head{display:flex;gap:10px;align-items:center;padding:13px 14px 9px;position:relative;}
.npc-portrait{width:48px;height:48px;border:1px solid rgba(217,183,106,.35);border-radius:50%;flex:none;background:radial-gradient(circle at 45% 35%,#4d4238,#16141a);display:grid;place-items:center;color:#d8c59d;position:relative;}
.npc-portrait svg{width:26px;height:26px;}
.dialogue-head h3{font-family:var(--font-display);font-size:15px;color:#f0dbb3;letter-spacing:.06em;}
.dialogue-head .npc-title{font-size:8px;letter-spacing:.12em;text-transform:uppercase;color:#9a8f78;margin-top:2px;}
.dialogue-close{margin-left:auto;width:30px;height:30px;display:grid;place-items:center;color:#82796a;align-self:flex-start;}
.dialogue-close svg{width:16px;height:16px;}
.dialogue-text{padding:2px 16px 11px;font-size:10.5px;line-height:1.65;color:#c4baaa;font-style:italic;min-height:45px;}
.dialogue-actions{display:flex;gap:6px;flex-wrap:wrap;padding:0 14px 10px;}
.dialogue-actions .btn{min-height:33px;font-size:8px;padding:0 11px;flex:1;min-width:80px;}
.dialogue-quest{margin:0 14px 10px;padding:8px;border:1px solid rgba(217,183,106,.14);background:rgba(217,183,106,.035);font-size:8.5px;color:#a99b80;}
.dialogue-quest b{display:block;color:#d8c59d;font-family:var(--font-display);font-size:10px;margin-bottom:2px;}
@keyframes dialogueIn{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}

/* modal */
.modal-backdrop{z-index:95;}
.modal.item-modal{max-width:380px;}
.modal-head h3{font-size:14px;letter-spacing:.06em;}
.modal-body{padding:14px;}
.modal-foot .btn{flex:1;}
.item-modal-card{padding:0;border:0;background:transparent;}
.item-modal-card::before{display:none;}
.confirm-text{font-size:10.5px;line-height:1.65;color:#b5ab99;}
.confirm-text b{color:#e8d5ae;}
.credits-scroll{max-height:60vh;}
.credits-scroll h3{font-family:var(--font-display);font-size:14px;color:#e8d5ae;margin-bottom:8px;}
.credits-scroll p{font-size:9.5px;line-height:1.7;color:#968e7f;margin:0 0 10px;}
.credits-scroll .credit-line{display:flex;justify-content:space-between;gap:12px;font-size:9px;color:#847c6e;padding:4px 0;border-bottom:1px solid rgba(255,255,255,.04);}
.credits-scroll .credit-line b{color:#bcaE92;font-weight:500;}

/* onboarding */
.onboarding{position:fixed;inset:0;z-index:100;background:radial-gradient(circle at 50% 35%,rgba(32,27,46,.8),rgba(3,3,6,.95));display:flex;align-items:center;justify-content:center;padding:22px;animation:fadeIn .35s both;}
.onboarding-card{width:100%;max-width:360px;border:1px solid rgba(217,183,106,.35);background:linear-gradient(165deg,rgba(25,23,31,.99),rgba(8,8,13,.995));padding:22px 18px 16px;position:relative;box-shadow:0 30px 80px rgba(0,0,0,.6);}
.onboarding-card::before{content:"";position:absolute;inset:5px;border:1px solid rgba(217,183,106,.07);pointer-events:none;}
.onboarding-icon{width:54px;height:54px;margin:0 auto 12px;border:1px solid rgba(217,183,106,.35);border-radius:50%;display:grid;place-items:center;color:var(--gold);background:radial-gradient(circle,rgba(217,183,106,.12),transparent);}
.onboarding-icon svg{width:28px;height:28px;}
.onboarding-card h2{font-family:var(--font-display);font-size:19px;text-align:center;color:#f2e3c2;letter-spacing:.05em;}
.onboarding-card p{font-size:10px;line-height:1.65;color:#a8a091;text-align:center;margin:8px 0 16px;min-height:48px;}
.onboarding-dots{display:flex;justify-content:center;gap:4px;margin-bottom:14px;}
.onboarding-dots i{width:5px;height:5px;border-radius:50%;background:#4b453c;}
.onboarding-dots i.on{background:var(--gold);}
.onboarding-actions{display:flex;gap:6px;}
.onboarding-actions .btn{flex:1;min-height:38px;font-size:9px;}

/* language */
.lang-compact{display:inline-flex;border:1px solid rgba(217,183,106,.25);background:rgba(5,6,10,.55);}
.lang-compact button{height:26px;padding:0 8px;font-size:8px;letter-spacing:.08em;color:#817a6e;}
.lang-compact button.on{color:#f2e2c0;background:rgba(217,183,106,.14);}

/* responsive */
@media(max-height:650px){
  .char-hero-wrap{height:236px;}
  .hud-bottom{height:200px;}
  .joystick{width:108px;height:108px;}
  .attack-cluster{width:142px;height:144px;}
