261:         this.finishGather(this.channel.node);
262:         this.channel = null;
263:       }
264:       this.moving = false;
265:       this.updateEffects(dt);
266:       this.updateMonsters(dt);
267:       this.updateLoot(dt);
268:       this.updateCamera(dt);
269:       return;
270:     }
271: 
272:     // movement
273:     let mx = 0, my = 0;
274:     const joy = this.joystick;
275:     if (joy.active) { mx += joy.x; my += joy.y; }
276:     if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) mx -= 1;
277:     if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) mx += 1;
278:     if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) my -= 1;
279:     if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) my += 1;
280:     const mag = Math.hypot(mx, my);
281:     this.moving = mag > 0.08;
282:     if (this.moving) {
283:       mx /= mag; my /= mag;
284:       const inCombat = this.monsters.some((m) => !m.dead && m.aggro && dist(m.x, m.y, player.x, player.y) < 300);
285:       const speedMul = inCombat ? 0.92 : 1 + (player.mount ? mountSpeed(player) : 0);
286:       const speed = player.stats.speed * speedMul;
287:       let nx = player.x + mx * speed * dt;
288:       let ny = player.y + my * speed * dt;
289:       const resolved = resolveCollision(nx, ny, this.data.props);
290:       player.x = clamp(resolved.x, 40, WORLD_SIZE - 40);
291:       player.y = clamp(resolved.y, 40, WORLD_SIZE - 40);
292:       if (Math.abs(mx) > 0.2) this.facing = mx > 0 ? 1 : -1;
293:       this.walkPhase = (this.walkPhase ?? 0) + dt * 9;
294:     }
295: 
296:     // regen
297:     if (!this.inCombat() && player.hp > 0) {
298:       player.hp = Math.min(player.stats.maxHp, player.hp + player.stats.hpRegen * dt);
299:       player.resource = Math.min(player.stats.maxResource, player.resource + player.stats.resourceRegen * dt);
300:     }
301: 
302:     if (this.attackHeld) this.tryBasicAttack();
303:     this.updateMonsters(dt);
304:     this.updateProjectiles(dt);
305:     this.updateEffects(dt);
306:     this.updateFloaters(dt);
307:     this.updateLoot(dt);
308:     this.updateInteraction();
309:     this.updateCamera(dt);
310:     this.updateNPCs();
311:     this.minimapTimer -= dt;
312:     if (this.minimapTimer <= 0) { this.drawMinimap(); this.minimapTimer = 0.35; }
313:     if (this.autosaveTimer == null) this.autosaveTimer = 20;
314:     this.autosaveTimer -= dt;
315:     if (this.autosaveTimer <= 0) { this.autosaveTimer = 25; this.save(); }
316:     // tutorial first steps
317:     if (!this.game.settings?.tutorialDone) this.tutorialProgress();
318:   }
319: 
320:   tutorialProgress() {
321:     const p = this.player;
322:     if (this.tutStep === 0 && this.moving) { this.tutStep = 1; App.ui?.tutorialStep?.(1); }
323:     if (this.tutStep === 1 && this.playerHasAttacked) { this.tutStep = 2; App.ui?.tutorialStep?.(2); }
324:     if (this.tutStep === 2 && this.playerUsedSkill) { this.tutStep = 3; App.ui?.tutorialStep?.(3); }
325:   }
326: 
327:   updateBuffs() {
328:     const now = Date.now();
329:     if (this.armorBuffUntil && now > this.armorBuffUntil) this.armorBuffUntil = 0;
330:     if (this.xpBuffUntil && now > this.xpBuffUntil) this.xpBuffUntil = 0;
331:     if (this.gatherBuffUntil && now > this.gatherBuffUntil) this.gatherBuffUntil = 0;
332:   }
333: 
334:   inCombat() {
335:     return this.monsters.some((m) => !m.dead && m.aggro && dist(m.x, m.y, this.player.x, this.player.y) < 420);
336:   }
337: 
338:   updateCamera(dt) {
339:     const viewH = VIEW_W * (this.h / this.w);
340:     const tx = clamp(this.player.x, viewH * 0 + VIEW_W / 2, WORLD_SIZE - VIEW_W / 2);
341:     const ty = clamp(this.player.y, viewH / 2, WORLD_SIZE - viewH / 2);
342:     const k = 1 - Math.pow(0.001, dt);
343:     this.camera.x += (tx - this.camera.x) * k;
344:     this.camera.y += (ty - this.camera.y) * k;
345:   }
346: 
347:   updateNPCs() {
348:     if (!this.npcs) return;
349:     for (const npc of this.npcs) {
350:       const zoneQuests = QUESTS.filter((q) => q.zone === this.zoneId && (q.npc === npc.id || (!q.npc && q.story)));
351:       let marker = null;
352:       for (const q of zoneQuests) {
353:         const e = this.player.quests[q.id];
354:         if (e?.state === 'done') { marker = 'done'; break; }
355:         if (!e) { marker = 'quest'; }
356:       }
357:       npc.marker = marker;
358:     }
359:   }
360: 
361:   // ── combat ──────────────────────────────────────────────────────────────
362:   get basicRange() { return this.player.classId === 'mage' ? 390 : this.player.classId === 'assassin' ? 105 : 118; }
363: 
364:   tryBasicAttack() {
365:     if (this.dead || this.channel) return;
366:     if (this.attackCooldown > 0) return;
367:     let target = this.target;
368:     if (!target) {
369:       target = this.nearestMonster(this.basicRange + 60);
370:       if (target) this.targetUid = target.uid;
371:     }
372:     if (!target) {
373:       if (this.attackHeld && this.time - (this.lastNoTargetToast ?? 0) > 2) {
374:         this.lastNoTargetToast = this.time;
375:         this.notify(t('hud.noTarget'));
376:       }
377:       this.attackCooldown = 0.35;
378:       return;
379:     }
380:     const d = dist(this.player.x, this.player.y, target.x, target.y);
381:     if (d > this.basicRange + (target.boss ? 30 * target.scale : 10)) {
382:       this.targetUid = null;
383:       this.attackCooldown = 0.3;
384:       return;
385:     }
386:     this.attackCooldown = this.player.classId === 'assassin' ? 0.55 : this.player.classId === 'warrior' ? 0.72 : 0.82;
387:     this.attackAnim = 1;
388:     this.playerHasAttacked = true;
389:     this.facing = target.x >= this.player.x ? 1 : -1;
390:     const empower = this.empowered > 0 ? 1.8 : 1;
391:     this.empowered = 0;
392:     let dmg = this.player.stats.attack * (0.92 + Math.random() * 0.16) * empower;
393:     const crit = Math.random() < this.player.stats.crit;
394:     if (crit) dmg *= this.player.stats.critDmg;
395:     this.hitMonster(target, dmg, { crit, type: 'basic' });
396:     this.gainResource(this.player.classId === 'warrior' ? 13 : this.player.classId === 'assassin' ? 9 : 5);
397:     this.applyLifesteal(dmg);
398:     this.addEffect({ kind: this.player.classId === 'mage' ? 'bolt' : 'slash', x: this.player.x, y: this.player.y - 34, tx: target.x, ty: target.y - 30, color: this.player.classId === 'mage' ? '#a8d8ff' : '#f0d090', life: 0.24, maxLife: 0.24, angle: Math.atan2(target.y - this.player.y, target.x - this.player.x) });
399:     this.sfx(this.player.classId === 'mage' ? 'cast' : 'slash');
400:     this.shakeTime = Math.max(this.shakeTime, 0.08);
401:   }
402: 
403:   useSkill(indexOrId) {
404:     if (this.dead || this.channel) return false;
405:     const cls = CLASSES[this.player.classId];
406:     const skill = typeof indexOrId === 'number' ? cls.skills[indexOrId] : cls.skills.find((s) => s.id === indexOrId);
407:     if (!skill) return false;
408:     if (this.player.level < skill.unlock) {
409:       this.notify(t('skill.unlockAt', { lv: skill.unlock }));
410:       return false;
411:     }
412:     if ((this.cooldowns[skill.id] ?? 0) > 0) return false;
413:     const res = this.player.classId === 'warrior' ? 'rage' : this.player.classId === 'mage' ? 'mana' : 'energy';
414:     if (this.player.resource < skill.cost) {
415:       this.notify(t('toast.noResource', { resource: t(`common.${res}`) }), 'bad');
416:       return false;
417:     }
418:     const target = this.target ?? this.nearestMonster(skill.type === 'single' ? skill.range : 300);
419:     if ((skill.type === 'single' || skill.type === 'dash') && (!target || dist(this.player.x, this.player.y, target.x, target.y) > skill.range + 40)) {
420:       this.notify(t('toast.needTarget'));
421:       return false;
422:     }
423:     this.player.resource -= skill.cost;
424:     this.playerUsedSkill = true;
425:     this.cooldowns[skill.id] = skill.cd;
426:     this.facing = target && target.x < this.player.x ? -1 : 1;
427:     this.sfx('cast');
428:     if (skill.type === 'single') {
429:       this.doSingleSkill(skill, target);
430:     } else if (skill.type === 'aoe') {
431:       this.doAoeSkill(skill);
432:     } else if (skill.type === 'ground') {
433:       this.doGroundSkill(skill, target);
434:     } else if (skill.type === 'buff') {
435:       this.doBuffSkill(skill);
436:     } else if (skill.type === 'dash') {
437:       this.doDashSkill(skill, target);
438:     }
439:     this.save();
440:     return true;
441:   }
442: 
443:   skillDamage(skill, mult = 1) {
444:     let dmg = this.player.stats.attack * skill.mult * mult * (0.94 + Math.random() * 0.12);
445:     const crit = Math.random() < this.player.stats.crit;
446:     if (crit) dmg *= this.player.stats.critDmg;
447:     return { dmg, crit };
448:   }
449: 
450:   doSingleSkill(skill, target) {
451:     const { dmg, crit } = this.skillDamage(skill);
452:     if (this.player.classId === 'mage') {
453:       this.projectiles.push({ x: this.player.x, y: this.player.y - 40, tx: target.x, ty: target.y - 30, speed: 760, color: skill.color, life: 1.2, onHit: () => this.hitMonster(target, dmg, { crit, skill }), trail: skill.color });
454:       this.addEffect({ kind: 'cast', x: this.player.x, y: this.player.y - 30, color: skill.color, life: 0.4, maxLife: 0.4 });
455:     } else {
456:       this.addEffect({ kind: 'slash', x: this.player.x, y: this.player.y - 34, tx: target.x, ty: target.y - 30, color: skill.color, life: 0.32, maxLife: 0.32, angle: Math.atan2(target.y - this.player.y, target.x - this.player.x) });
457:       this.hitMonster(target, dmg, { crit, skill });
458:       if (skill.effect === 'stun') { target.stunUntil = this.time + 1.45; this.floater(target.x, target.y - 70, t('combat.stunned'), '#f2d27a'); }
459:       if (skill.effect === 'poison') { target.poisonUntil = Math.max(target.poisonUntil, this.time + 6); target.poisonTick = 0; }
460:     }
461:     this.applyLifesteal(dmg);
462:   }
463: 
464:   doAoeSkill(skill) {
465:     const targets = this.monsters.filter((m) => !m.dead && dist(m.x, m.y, this.player.x, this.player.y) <= skill.radius + (m.boss ? 26 * m.scale : 0));
466:     this.addEffect({ kind: 'ring', x: this.player.x, y: this.player.y - 12, r: skill.radius, color: skill.color, life: 0.55, maxLife: 0.55 });
467:     this.addEffect({ kind: 'burst', x: this.player.x, y: this.player.y - 30, color: skill.color, life: 0.4, maxLife: 0.4 });
468:     for (const m of targets) {
469:       const { dmg, crit } = this.skillDamage(skill, 0.9 + Math.random() * 0.2);
470:       this.hitMonster(m, dmg, { crit, skill });
471:       if (skill.effect === 'slow') { m.slowUntil = this.time + 4; this.floater(m.x, m.y - 66, t('combat.slowed'), '#9fe8ff'); }
472:       if (skill.effect === 'bleed') { m.burnUntil = Math.max(m.burnUntil, this.time + 4); m.burnTick = 0; }
473:       this.applyLifesteal(dmg);
474:     }
475:     if (!targets.length) this.notify(t('toast.needTarget'));
476:     this.shakeTime = Math.max(this.shakeTime, 0.16);
477:   }
478: 
479:   doGroundSkill(skill, target) {
480:     const tx = target ? target.x : this.player.x + this.facing * 150;
481:     const ty = target ? target.y : this.player.y;
482:     this.addEffect({ kind: 'telegraph', x: tx, y: ty, r: skill.radius, color: skill.color, life: 0.7, maxLife: 0.7, ground: true });
483:     setTimeout(() => {
484:       if (!this.running) return;
485:       this.addEffect({ kind: 'meteor', x: tx, y: ty, r: skill.radius, color: skill.color, life: 0.8, maxLife: 0.8 });
486:       this.addEffect({ kind: 'ring', x: tx, y: ty - 8, r: skill.radius, color: skill.color, life: 0.55, maxLife: 0.55 });
487:       for (const m of this.monsters) {
488:         if (m.dead) continue;
489:         if (dist(m.x, m.y, tx, ty) <= skill.radius + 12) {
490:           const { dmg, crit } = this.skillDamage(skill, 0.92 + Math.random() * 0.16);
491:           this.hitMonster(m, dmg, { crit, skill });
492:           if (skill.effect === 'burn') { m.burnUntil = Math.max(m.burnUntil, this.time + 5); m.burnTick = 0; }
493:           this.applyLifesteal(dmg);
494:         }
495:       }
496:       this.shakeTime = Math.max(this.shakeTime, 0.3);
497:     }, 650);
498:   }
499: 
500:   doBuffSkill(skill) {
501:     const heal = this.player.stats.maxHp * 0.24;
502:     this.player.hp = Math.min(this.player.stats.maxHp, this.player.hp + heal);
503:     this.armorBuffUntil = Date.now() + 8000;
504:     this.floater(this.player.x, this.player.y - 74, `+${Math.round(heal)}`, '#8ce07a');
505:     this.addEffect({ kind: 'pillar', x: this.player.x, y: this.player.y, color: skill.color, life: 0.9, maxLife: 0.9 });
506:   }
507: 
508:   doDashSkill(skill, target) {
509:     const angle = Math.atan2(target.y - this.player.y, target.x - this.player.x);
510:     let nx = target.x - Math.cos(angle) * 48;
511:     let ny = target.y - Math.sin(angle) * 48;
512:     const resolved = resolveCollision(nx, ny, this.data.props);
513:     this.addEffect({ kind: 'dash', x: this.player.x, y: this.player.y - 30, tx: resolved.x, ty: resolved.y - 30, color: skill.color, life: 0.4, maxLife: 0.4 });
514:     this.player.x = clamp(resolved.x, 40, WORLD_SIZE - 40);
515:     this.player.y = clamp(resolved.y, 40, WORLD_SIZE - 40);
516:     this.camera.x = this.player.x; this.camera.y = this.player.y;
517:     const { dmg, crit } = this.skillDamage(skill);
518:     this.hitMonster(target, dmg, { crit, skill });
519:     this.empowered = 1;
520:     this.addEffect({ kind: 'burst', x: this.player.x, y: this.player.y - 30, color: skill.color, life: 0.5, maxLife: 0.5 });
521:     this.applyLifesteal(dmg);
522:   }
523: 
524:   applyLifesteal(dmg) {
525:     const ls = this.player.stats.lifesteal;
526:     if (ls > 0) {
527:       const heal = dmg * ls;
528:       if (heal > 1) this.player.hp = Math.min(this.player.stats.maxHp, this.player.hp + heal);
529:     }
530:   }
531: 
532:   hitMonster(mon, raw, opts = {}) {
533:     if (!mon || mon.dead) return;
534:     const red = mon.defense / (mon.defense + 95 + mon.level * 8);
535:     let dmg = Math.max(1, Math.round(raw * (1 - red)));
536:     if (this.armorBuffUntil > 0) dmg = Math.round(dmg * 1.04);
537:     mon.hp -= dmg;
538:     mon.flash = 0.12;
539:     mon.aggro = true;
540:     mon.lastHit = this.time;
541:     if (!mon.boss) mon.state = 'chase';
542:     this.hitCombo++;
543:     this.comboTimer = 1.6;
544:     this.floater(mon.x + (Math.random() - 0.5) * 16, mon.y - 64 - (mon.scale - 1) * 20, `${dmg}${opts.crit ? '!' : ''}`, opts.crit ? '#ffd76e' : opts.skill ? opts.skill.color : '#f0e6d0', opts.crit ? 1.35 : 1);
545:     if (opts.crit) {
546:       this.addEffect({ kind: 'crit', x: mon.x, y: mon.y - 40, color: '#ffd76e', life: 0.4, maxLife: 0.4 });
547:       this.sfx('crit');
548:     }
549:     this.addEffect({ kind: 'impact', x: mon.x, y: mon.y - 28, color: opts.skill?.color ?? '#ffcf8a', life: 0.3, maxLife: 0.3 });
550:     if (mon.hp <= 0) this.killMonster(mon);
551:     else this.sfx('hit');
552:   }
553: 
554:   killMonster(mon) {
555:     if (mon.dead) return;
556:     mon.dead = true;
557:     mon.hp = 0;
558:     mon.respawnAt = this.time + (mon.boss ? 95 : mon.elite ? 55 : 28);
559:     mon.aggro = false;
560:     this.player.kills = (this.player.kills ?? 0) + 1;
561:     if (mon.boss) {
562:       this.player.bossKills = (this.player.bossKills ?? 0) + 1;
563:       this.bossEngaged = false;
564:       this.bossWarned = false;
565:       this.bossSlamTimer = 4;
566:     }
567:     if (this.targetUid === mon.uid) this.targetUid = null;
568:     const xpGain = mon.xp * (this.xpBuffUntil > Date.now() ? 1.25 : 1);
569:     const res = addXP(this.player, xpGain);
570:     this.floater(mon.x, mon.y - 82, `+${Math.round(xpGain)} XP`, '#b9d6ff', 0.95);
571:     if (res.levels > 0) {
572:       this.addEffect({ kind: 'levelup', x: this.player.x, y: this.player.y, color: '#f4e3b0', life: 1.6, maxLife: 1.6 });
573:       this.notify(t('hud.levelUp') + ' ' + t('hud.levelUpText', { lv: this.player.level }), 'good');
574:       this.sfx('levelup');
575:       this.game.flashLevel = this.time;
576:       this.save();
577:     }
578:     // drops
579:     const goldAmount = Math.round(mon.gold * (1 + this.player.stats.goldFind));
580:     this.spawnLoot({ type: 'gold', x: mon.x + (Math.random() - 0.5) * 22, y: mon.y + 4, amount: goldAmount, color: '#d9b76a' });
581:     const itemChance = mon.boss ? 1 : mon.elite ? 0.95 : 0.68;
582:     if (Math.random() < itemChance) {
583:       const rarity = weighted(Math.random, DROP_WEIGHTS);
584:       const level = clamp(this.zone.min + Math.floor(Math.random() * 4), 1, 60);
585:       const classId = Math.random() < 0.82 ? this.player.classId : ['warrior', 'mage', 'assassin'][Math.floor(Math.random() * 3)];
586:       const slots = ['weapon', 'offhand', 'helm', 'chest', 'gloves', 'boots', 'belt', 'ring', 'amulet'];
587:       const slot = slots[Math.floor(Math.random() * slots.length)];
588:       const item = makeEquip({ classId, slot, rarity, tier: 'T3', level });
589:       this.spawnLoot({ type: 'item', x: mon.x + (Math.random() - 0.5) * 30, y: mon.y + 2, item, color: RARITY[rarity].color });
590:     }
591:     if (Math.random() < (mon.boss ? 1 : mon.elite ? 0.22 : 0.045)) {
592:       this.spawnLoot({ type: 'gem', x: mon.x + (Math.random() - 0.5) * 26, y: mon.y + 6, amount: 1 + (mon.boss ? 3 : 0), color: '#8fd8ee' });
593:     }
594:     if (mon.boss) {
595:       const stone = makeBossStone(this.zone.id, this.zone.boss.stoneName);
596:       this.spawnLoot({ type: 'stone', x: mon.x + 10, y: mon.y, item: stone, color: '#f4e3b0' });
597:       if (!this.player.bossFirstKills[this.zone.id]) {
598:         this.player.bossFirstKills[this.zone.id] = true;
599:         addGems(this.player, 20);
600:         this.floater(mon.x, mon.y - 110, '+20 Gems', '#8fd8ee', 1.1, 1.4);
601:       }
602:       this.notify(`${tx(mon.name)} — ${t('combat.victory')}`, 'good');
603:     }
604:     // quests
605:     const done = advanceQuests(this.player, 'kill', mon.defId, 1);
606:     if (mon.elite) advanceQuests(this.player, 'killElite', mon.defId, 1).forEach((q) => done.push(q));
607:     if (mon.boss) advanceQuests(this.player, 'boss', mon.defId, 1).forEach((q) => done.push(q));
608:     for (const q of done) {
609:       this.notify(t('quest.completeToast', { name: tx(q.name) }), 'good');
610:       this.sfx('quest');
611:     }
612:     this.addEffect({ kind: 'soul', x: mon.x, y: mon.y - 30, color: mon.boss ? '#ffcf8a' : '#b9d6ff', life: 0.9, maxLife: 0.9, scale: mon.scale });
613:     this.save();
614:   }
615: 
616:   damagePlayer(amount, source) {
617:     if (this.dead || this.time < (this.invulnUntil ?? 0)) return;
618:     const red = this.player.stats.armor / (this.player.stats.armor + 92 + this.player.level * 9);
619:     let dmg = Math.max(1, Math.round(amount * (1 - red) * 0.9));
620:     this.player.hp -= dmg;
621:     this.damageFlash = 1;
622:     this.floater(this.player.x + (Math.random() - 0.5) * 14, this.player.y - 70, `-${dmg}`, '#ff8a80', 1.05);
623:     this.addEffect({ kind: 'impact', x: this.player.x, y: this.player.y - 30, color: '#ff6b63', life: 0.3, maxLife: 0.3 });
624:     this.shakeTime = Math.max(this.shakeTime, 0.22);
625:     this.sfx('hurt');
626:     if (this.player.mount) this.player.mount = null;
627:     if (this.player.hp <= 0) { this.player.hp = 0; this.die(); }
628:   }
629: 
630:   die() {
631:     this.dead = true;
632:     this.targetUid = null;
633:     this.attackHeld = false;
634:     this.channel = null;
635:     this.sfx('death');
636:     this.save(true);
637:     App.ui?.onDeath?.();
638:   }
639: 
640:   respawn() {
641:     const camp = this.data.camp;
642:     this.player.hp = Math.round(this.player.stats.maxHp * 0.6);
643:     this.player.resource = Math.round(this.player.stats.maxResource * 0.4);
644:     this.player.x = camp.x;
645:     this.player.y = camp.y + 40;
646:     this.camera.x = this.player.x; this.camera.y = this.player.y;
647:     this.dead = false;
648:     this.invulnUntil = this.time + 2.5;
649:     this.targetUid = null;
650:     for (const m of this.monsters) {
651:       if (!m.boss) { m.aggro = false; m.x = m.homeX; m.y = m.homeY; m.state = 'idle'; }
652:     }
653:     this.save();
654:   }
