674:   useConsumableItem(item) {
675:     if (!item) return false;
676:     if (item.kind !== 'consumable') return false;
677:     const p = this.player;
678:     if (item.id === 'healPotion') {
679:       if (p.hp >= p.stats.maxHp) { this.notify(t('toast.potionFull')); return false; }
680:       p.hp = Math.min(p.stats.maxHp, p.hp + p.stats.maxHp * (item.heal ?? 0.45));
681:       this.floater(p.x, p.y - 70, `+${Math.round(p.stats.maxHp * (item.heal ?? 0.45))}`, '#8ce07a');
682:     } else if (item.id === 'manaPotion') {
683:       p.resource = Math.min(p.stats.maxResource, p.resource + p.stats.maxResource * (item.resource ?? 0.45));
684:       this.floater(p.x, p.y - 70, `+${Math.round(p.stats.maxResource * (item.resource ?? 0.45))}`, '#8fd8ee');
685:     } else if (item.id === 'elixir') {
686:       this.xpBuffUntil = Date.now() + 30 * 60000;
687:       this.notify('+25% XP (30m)', 'good');
688:     } else if (item.id === 'charm') {
689:       this.gatherBuffUntil = Date.now() + 30 * 60000;
690:       this.notify('+25% ' + t('char.gatherSpeed') + ' (30m)', 'good');
691:     } else if (item.id === 'moonbread') {
692:       p.hp = Math.min(p.stats.maxHp, p.hp + p.stats.maxHp * 0.3);
693:       p.resource = Math.min(p.stats.maxResource, p.resource + p.stats.maxResource * 0.3);
694:     }
695:     if ((item.qty ?? 1) > 1) item.qty--; else {
696:       const idx = p.inventory.indexOf(item);
697:       if (idx >= 0) p.inventory.splice(idx, 1);
698:     }
699:     this.sfx('heal');
700:     this.save();
701:     return true;
702:   }
