830:       this.bossSlamTimer = 6.5;
831:       const tx = this.player.x, ty = this.player.y;
832:       const warning = { kind: 'telegraph', x: tx, y: ty, r: 120, color: '#ff7a5c', life: 1.2, maxLife: 1.2, ground: true, boss: true };
833:       this.addEffect(warning);
834:       this.sfx('bossCast');
835:       setTimeout(() => {
836:         if (!this.running || this.dead) return;
837:         this.addEffect({ kind: 'ring', x: tx, y: ty - 4, r: 120, color: '#ff7a5c', life: 0.5, maxLife: 0.5 });
838:         this.addEffect({ kind: 'burst', x: tx, y: ty - 20, color: '#ff9a5c', life: 0.6, maxLife: 0.6 });
839:         if (dist(this.player.x, this.player.y, tx, ty) < 120) this.damagePlayer(boss.attack * 2.3, boss);
840:         this.shakeTime = 0.35;
841:       }, 1200);
842:     }
843:   }
