870:   collectLoot(l) {
871:     if (!l || l.collected) return;
872:     const p = this.player;
873:     if (l.type === 'gold') {
874:       addGold(p, l.amount);
875:       this.floater(p.x, p.y - 64, `+${l.amount}g`, '#f4d78a', 0.9);
