912:   // ── gathering / interaction ─────────────────────────────────────────────
913:   updateInteraction() {
914:     const p = this.player;
915:     let best = null, bd = 78;
916:     for (const npc of this.npcs ?? []) {
917:       const d = dist(p.x, p.y, npc.x, npc.y);
918:       if (d < bd) { bd = d; best = { kind: 'npc', ref: npc, label: t('npc.talkTo', { name: t(npc.nameKey) }), icon: 'talk' }; }
919:     }
920:     const portal = this.data.portal;
921:     const pd = dist(p.x, p.y, portal.x, portal.y);
922:     if (pd < 95 && pd < bd) { bd = pd; best = { kind: 'portal', ref: portal, label: tx(portal.label), icon: 'portal' }; }
923:     for (const node of this.nodes) {
924:       if (!node.ready) continue;
925:       const d = dist(p.x, p.y, node.x, node.y);
926:       if (d < 62 && d < bd) { bd = d; best = { kind: 'node', ref: node, label: `${t('common.gather')} · ${t(`gather.${node.type}`)}`, icon: 'herb' }; }
927:     }
928:     this.interaction = best;
929:   }
