1006:   // ── render ──────────────────────────────────────────────────────────────
1007:   render(dt) {
1008:     const ctx = this.ctx;
1009:     if (!this.data) return;
1010:     const scale = this.w / VIEW_W;
1011:     const viewH = this.h / scale;
1012:     const camX = this.camera.x, camY = this.camera.y;
1013:     let shakeX = 0, shakeY = 0;
1014:     if (this.shakeTime > 0) {
1015:       shakeX = (Math.random() - 0.5) * 8 * Math.min(1, this.shakeTime * 4);
1016:       shakeY = (Math.random() - 0.5) * 8 * Math.min(1, this.shakeTime * 4);
1017:     }
1018:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
1019:     ctx.fillStyle = '#050508';
1020:     ctx.fillRect(0, 0, this.w, this.h);
1021:     ctx.save();
1022:     ctx.scale(scale, scale);
1023:     ctx.translate(VIEW_W / 2 - camX + shakeX / scale, viewH / 2 - camY + shakeY / scale);
1024: 
1025:     // terrain
1026:     ctx.drawImage(this.data.terrain, 0, 0, WORLD_SIZE, WORLD_SIZE);
1027: 
1028:     // ground ambient light pools
1029:     const zone = this.zone;
1030:     ctx.save();
1031:     const amb = ctx.createRadialGradient(this.player.x, this.player.y, 50, this.player.x, this.player.y, 380);
1032:     amb.addColorStop(0, hexA(zone.palette.light, 0.04)); amb.addColorStop(1, 'rgba(0,0,0,0)');
1033:     ctx.fillStyle = amb; ctx.fillRect(this.player.x - 400, this.player.y - 400, 800, 800);
1034:     ctx.restore();
1035: 
1036:     // ground effects (telegraphs, rings)
1037:     for (const e of this.effects) {
1038:       if (e.kind === 'telegraph') this.drawTelegraph(e);
1039:     }
1040:     if (this.channel) this.drawChannelRing();
1041: 
1042:     // renderables sorted by feet Y
1043:     const renderables = [];
1044:     for (const prop of this.data.props) {
1045:       renderables.push({ y: prop.y, draw: () => this.drawProp(prop) });
1046:     }
1047:     for (const d of this.data.decorations) renderables.push({ y: d.y, draw: () => art.drawDecoration(ctx, d, this.time) });
1048:     for (const npc of this.npcs ?? []) renderables.push({ y: npc.y, draw: () => art.drawNPC(ctx, npc, this.time) });
1049:     renderables.push({ y: this.data.portal.y, draw: () => art.drawPortal(ctx, this.data.portal, this.time, zone.camp) });
1050:     for (const node of this.nodes) renderables.push({ y: node.y, draw: () => art.drawGatherNode(ctx, node, this.time) });
1051:     for (const l of this.loot) renderables.push({ y: l.y, draw: () => art.drawLoot(ctx, l, this.time) });
1052:     for (const m of this.monsters) {
1053:       if (m.dead) continue;
1054:       renderables.push({ y: m.y, draw: () => this.drawMonster(m) });
1055:     }
1056:     renderables.push({ y: this.player.y, draw: () => {
1057:       art.drawWorldHero(ctx, this.player, this.player.x, this.player.y, this.time, {
1058:         moving: this.moving, facing: this.facing, attackAnim: this.attackAnim, combatGlow: this.inCombat(),
1059:       });
1060:       if (this.interaction) art.drawInteractRing(ctx, this.interaction.ref.x, this.interaction.ref.y, this.time);
1061:     } });
1062:     renderables.sort((a, b) => a.y - b.y);
1063:     for (const r of renderables) r.draw();
1064: 
1065:     // effects above ground
1066:     for (const e of this.effects) {
1067:       if (e.kind !== 'telegraph') this.drawEffect(e);
1068:     }
1069:     // projectiles
