132: /* Language switch */
133: .lang-switch{display:inline-flex;border:1px solid rgba(217,183,106,.3);background:rgba(6,7,11,.55);}
134: .lang-switch button{padding:7px 12px;font-size:9.5px;letter-spacing:.12em;color:#8e897e;}
135: .lang-switch button.on{background:linear-gradient(180deg,rgba(217,183,106,.24),rgba(217,183,106,.08));color:#f6e9c8;}
