227: export function makeBossStone(zoneId, bossName) {
228:   const rng = rngFrom('stone', zoneId, Date.now(), Math.random());
229:   const count = 2 + (rng() > 0.35 ? 1 : 0);
230:   const picked = [];
231:   const pool = STONE_BONUS_POOL.slice();
232:   for (let i = 0; i < count; i++) {
233:     const idx = Math.floor(rng() * pool.length);
234:     const b = pool.splice(idx, 1)[0];
235:     const value = b.min + rng() * (b.max - b.min);
236:     picked.push({ stat: b.stat, value: +value.toFixed(4), pct: b.pct });
237:   }
238:   return {
239:     uid: `stone_${zoneId}_${Date.now().toString(36)}_${Math.floor(rng() * 1e6)}`,
240:     kind: 'stone', name: bossName, zone: zoneId, bonuses: picked, tradeable: false, fusable: false, rarity: 'legendary',
241:   };
242: }
